/**
 * git 45가지와 패키지·런타임 25가지의 한 줄 설명 — 열 언어.
 *
 * 명령 이름과 옵션은 프로그램이 정한 것이라 옮기지 않는다. git reset은 어디서나
 * git reset이고 --hard는 --hard다. 옮기는 것은 "이것이 무슨 일을 하고 사람들이
 * 무엇을 잘못 아는가" 한 문장뿐이다.
 *
 * 열 칸을 배열로 적는다 — 순서는 ko·en·es·pt·ja·de·fr·hi·zh·tw.
 */
import type { Ten } from './types.ts';

export const CMD_DESC_DEV: Record<string, Ten> = {
  /* ───────── git — 만들고 가져오기 ───────── */
  'git-init': ['폴더 하나를 새 git 저장소로 만듭니다 — init만으로는 아무 파일도 추적되지 않아 add와 commit이 따로 필요합니다.', 'Turns a folder into a new git repository; init alone tracks nothing, so add and commit still have to happen.', 'Convierte una carpeta en un repositorio git nuevo; init por sí solo no rastrea nada, aún hacen falta add y commit.', 'Transforma uma pasta em um repositório git novo; init sozinho não rastreia nada, ainda faltam add e commit.', 'フォルダーを新しいgitリポジトリにします。initだけではファイルは追跡されず、addとcommitが別に必要です。', 'Macht aus einem Ordner ein neues git-Repository; init allein verfolgt noch keine Datei, add und commit fehlen weiterhin.', "Transforme un dossier en nouveau dépôt git ; init seul ne suit aucun fichier, il faut encore add et commit.", 'किसी फ़ोल्डर को नया git repository बना देता है; सिर्फ़ init से कोई फ़ाइल ट्रैक नहीं होती, add और commit अलग से करने पड़ते हैं।', '把一个文件夹变成新的 git 仓库；只用 init 不会跟踪任何文件，还要再 add 和 commit。', '把一個資料夾變成新的 git 儲存庫；只用 init 不會追蹤任何檔案，還要再 add 和 commit。'],
  'git-clone': ['원격 저장소를 이력째 복사해 옵니다 — --depth 1로 얕게 받으면 옛 커밋과 다른 브랜치가 없어 나중에 --unshallow가 필요합니다.', 'Copies a remote repository with its history; a --depth 1 clone has no old commits and no other branches, so --unshallow is needed later.', 'Copia un repositorio remoto con su historia; un clon con --depth 1 no trae commits antiguos ni otras ramas, y luego hace falta --unshallow.', 'Copia um repositório remoto com o histórico; um clone --depth 1 não traz commits antigos nem outros branches, e depois exige --unshallow.', 'リモートのリポジトリを履歴ごと複製します。--depth 1で浅く取ると古いコミットや他のブランチが無く、後で--unshallowが必要になります。', 'Kopiert ein entferntes Repository samt Historie; ein Klon mit --depth 1 hat keine alten Commits und keine anderen Branches, dafür braucht es später --unshallow.', "Copie un dépôt distant avec son historique ; un clone --depth 1 n'a ni anciens commits ni autres branches, d'où --unshallow plus tard.", 'रिमोट repository को इतिहास के साथ कॉपी करता है; --depth 1 वाले clone में पुराने commit और दूसरी branch नहीं होतीं, बाद में --unshallow चाहिए।', '把远端仓库连历史一起复制下来；--depth 1 的浅克隆没有旧提交和别的分支，之后得用 --unshallow 补齐。', '把遠端儲存庫連歷史一起複製下來；--depth 1 的淺複製沒有舊提交和其他分支，之後得用 --unshallow 補齊。'],
  'git-config': ['git의 설정을 읽고 씁니다 — --global을 빼면 지금 저장소에만 적혀서 새로 클론한 곳은 그 설정을 모릅니다.', 'Reads and writes git settings; without --global it only touches this repository, which is why a fresh clone forgets the setting.', 'Lee y escribe la configuración de git; sin --global solo afecta a este repositorio, por eso un clon nuevo no la conoce.', 'Lê e escreve as configurações do git; sem --global vale só para este repositório, por isso um clone novo não sabe dela.', 'gitの設定を読み書きします。--globalを付けないと今のリポジトリにしか書かれず、新しくクローンした所には引き継がれません。', 'Liest und schreibt git-Einstellungen; ohne --global gilt es nur für dieses Repository, ein frischer Klon kennt es also nicht.', "Lit et écrit la configuration de git ; sans --global, seul ce dépôt est concerné, un nouveau clone l'ignore donc.", 'git की सेटिंग पढ़ता और लिखता है; --global के बिना यह सिर्फ़ इसी repository में जाती है, नए clone को उसका पता नहीं होता।', '读写 git 的配置；不加 --global 只写进当前仓库，重新克隆一份就没有这条设置了。', '讀寫 git 的設定；不加 --global 只會寫進目前的儲存庫，重新複製一份就沒有這條設定了。'],
  'git-init-bare': ['작업 폴더가 없는 저장소를 만듭니다 — 받아만 두는 곳이라 안의 파일을 고칠 수 없지만, 체크아웃된 브랜치로 밀어 넣다 거절당하는 일도 없습니다.', 'Creates a repository with no working tree, meant only to be pushed to; you cannot edit files in it, but pushes never bounce off a checked-out branch.', 'Crea un repositorio sin árbol de trabajo, pensado solo para recibir push; no puedes editar archivos dentro, pero ningún push choca con una rama activa.', 'Cria um repositório sem árvore de trabalho, feito só para receber push; não dá para editar arquivos nele, mas nenhum push é recusado por causa do branch ativo.', '作業ツリーを持たないリポジトリを作ります。受け取る専用なので中のファイルは編集できませんが、チェックアウト中のブランチへのpushが拒否されることもありません。', 'Erzeugt ein Repository ohne Arbeitsverzeichnis, nur zum Hineinpushen; Dateien lassen sich darin nicht bearbeiten, dafür scheitert kein Push am ausgecheckten Branch.', "Crée un dépôt sans copie de travail, uniquement destiné à recevoir des push ; on n'y édite pas de fichiers, mais aucun push n'est refusé à cause de la branche active.", 'बिना working tree वाला repository बनाता है, जो सिर्फ़ push लेने के लिए होता है; उसमें फ़ाइलें संपादित नहीं होतीं, पर checked-out branch की वजह से कोई push रुकता भी नहीं।', '建立没有工作目录的仓库，专门用来接收 push；里面的文件无法编辑，但也不会因为分支正被检出而拒绝 push。', '建立沒有工作目錄的儲存庫，專門用來接收 push；裡面的檔案無法編輯，但也不會因為分支正被簽出而拒絕 push。'],

  /* ───────── git — 담고 커밋하기 ───────── */
  'git-add': ['지금 파일 상태를 커밋 대기 자리에 올립니다 — 올린 뒤 또 고치면 그 수정은 담기지 않아 다시 add해야 합니다.', 'Stages the file as it looks right now; editing it again after add leaves that change out, so you have to add once more.', 'Prepara el archivo tal como está en ese instante; si lo editas después del add, ese cambio no entra y hay que volver a añadirlo.', 'Prepara o arquivo como ele está naquele instante; se você editar depois do add, essa mudança fica de fora e precisa de outro add.', '今この瞬間のファイルの中身をコミット待ちに載せます。addした後にまた直すとその修正は入らないので、もう一度addします。', 'Nimmt die Datei so auf, wie sie in diesem Moment aussieht; bearbeitet man sie nach dem add erneut, fehlt diese Änderung und man muss nochmal add ausführen.', "Indexe le fichier tel qu'il est à cet instant ; si vous le modifiez après le add, cette modification reste dehors et il faut refaire add.", 'फ़ाइल को उसी क्षण की हालत में staging पर रखता है; add के बाद फिर बदलाव किया तो वह छूट जाता है और दोबारा add करना पड़ता है।', '把文件当下的内容放进暂存区；add 之后再改，这次的改动不会进去，得再 add 一次。', '把檔案當下的內容放進暫存區；add 之後又改，這次的改動不會進去，得再 add 一次。'],
  'git-commit': ['스테이지에 올린 것만 한 덩어리로 기록합니다 — -a는 추적 중인 파일만 담아 새로 만든 파일은 빠집니다.', 'Records what is staged as one commit; -a picks up modified tracked files only, so brand-new files are left out.', 'Registra lo preparado como un commit; -a solo toma archivos ya rastreados, así que los nuevos quedan fuera.', 'Registra o que está preparado como um commit; -a pega só arquivos já rastreados, então os novos ficam de fora.', 'ステージに載せたものだけを一つのコミットとして記録します。-aは追跡中のファイルしか拾わないので、新しく作ったファイルは入りません。', 'Schreibt das Vorbereitete als einen Commit; -a nimmt nur bereits verfolgte Dateien mit, neue bleiben außen vor.', "Enregistre ce qui est indexé en un commit ; -a ne prend que les fichiers déjà suivis, les nouveaux restent dehors.", 'staging में रखी चीज़ों को एक commit के रूप में दर्ज करता है; -a सिर्फ़ पहले से ट्रैक हो रही फ़ाइलें लेता है, नई फ़ाइलें छूट जाती हैं।', '把暂存区里的内容记成一个提交；-a 只会带上已跟踪文件的改动，新建的文件不算。', '把暫存區裡的內容記成一個提交；-a 只會帶上已追蹤檔案的改動，新建的檔案不算。'],
  'git-status': ['무엇이 스테이지에 있고 무엇이 아직 아닌지 보여줍니다 — 추적되지 않은 파일은 폴더 이름으로 뭉쳐 나오니 낱낱이 보려면 -uall을 붙입니다.', 'Shows what is staged, changed and untracked; untracked files are collapsed into folder names unless you add -uall.', 'Muestra qué está preparado, cambiado o sin rastrear; los archivos nuevos se agrupan por carpeta salvo que añadas -uall.', 'Mostra o que está preparado, alterado ou sem rastreio; arquivos novos aparecem agrupados por pasta a menos que use -uall.', '何がステージに載り、何がまだかを見せます。追跡外のファイルはフォルダー名にまとめられるので、一つずつ見るには-uallを付けます。', 'Zeigt, was vorbereitet, geändert oder unverfolgt ist; unverfolgte Dateien werden zu Ordnernamen zusammengefasst, solange -uall fehlt.', "Montre ce qui est indexé, modifié ou non suivi ; les fichiers non suivis sont regroupés par dossier sans -uall.", 'बताता है क्या staged है, क्या बदला है और क्या untracked; untracked फ़ाइलें फ़ोल्डर के नाम में सिमट जाती हैं, एक-एक देखने के लिए -uall चाहिए।', '显示哪些已暂存、哪些改了、哪些还没被跟踪；未跟踪的文件默认只按文件夹折叠显示，要逐个看得加 -uall。', '顯示哪些已暫存、哪些改了、哪些還沒被追蹤；未追蹤的檔案預設只按資料夾折疊顯示，要逐個看得加 -uall。'],
  'git-diff': ['아직 스테이지에 올리지 않은 수정만 보여줍니다 — add한 뒤에는 비어 보이니 그때는 --staged로 봅니다.', 'Shows only the changes you have not staged yet, which is why it looks empty right after git add — use --staged then.', 'Muestra solo los cambios que aún no has preparado; por eso parece vacío justo después de git add: usa --staged.', 'Mostra só as mudanças que ainda não foram preparadas; é por isso que parece vazio logo após git add — use --staged.', 'まだステージに載せていない変更だけを見せます。addした直後は空に見えるので、そのときは--stagedで見ます。', 'Zeigt nur die noch nicht vorbereiteten Änderungen — deshalb wirkt es direkt nach git add leer, dann hilft --staged.', "N'affiche que les modifications non encore indexées : après un git add, cela paraît vide, il faut alors --staged.", 'सिर्फ़ वे बदलाव दिखाता है जो अभी staged नहीं हैं; इसीलिए git add के तुरंत बाद खाली लगता है — तब --staged लगाएँ।', '只显示还没暂存的改动；所以刚 git add 完看着是空的，那时要用 --staged。', '只顯示還沒暫存的改動；所以剛 git add 完看起來是空的，那時要用 --staged。'],
  'git-log': ['커밋 이력을 새것부터 보여줍니다 — 지금 HEAD의 조상만 나오니 다른 브랜치까지 보려면 --all이 필요합니다.', 'Lists commit history newest first, but only the ancestors of the current HEAD — other branches need --all.', 'Lista el historial del más nuevo al más viejo, pero solo los antecesores del HEAD actual: otras ramas requieren --all.', 'Lista o histórico do mais novo ao mais antigo, mas só os ancestrais do HEAD atual: outros branches exigem --all.', 'コミット履歴を新しい順に見せますが、出るのは今のHEADの祖先だけで、他のブランチまで見るには--allが必要です。', 'Listet die Historie mit dem neuesten Commit zuerst, aber nur die Vorfahren des aktuellen HEAD — andere Branches brauchen --all.', "Liste l'historique du plus récent au plus ancien, mais seulement les ancêtres du HEAD courant : les autres branches exigent --all.", 'commit इतिहास नए से पुराने क्रम में दिखाता है, पर सिर्फ़ मौजूदा HEAD के पूर्वज; बाकी branch देखने के लिए --all चाहिए।', '按从新到旧列出提交历史，但只列当前 HEAD 的祖先，要看别的分支得加 --all。', '按從新到舊列出提交歷史，但只列目前 HEAD 的祖先，要看其他分支得加 --all。'],
  'git-show': ['커밋 하나의 메시지와 변경을 펼쳐 보여줍니다 — <commit>:<path> 꼴로 적으면 작업 파일을 건드리지 않고 옛 내용만 꺼내 볼 수 있습니다.', 'Prints one commit with its message and diff; the <commit>:<path> form pulls out an old version of a file without touching your working copy.', 'Imprime un commit con su mensaje y su diff; la forma <commit>:<ruta> saca una versión antigua del archivo sin tocar tu copia de trabajo.', 'Imprime um commit com mensagem e diff; a forma <commit>:<caminho> tira uma versão antiga do arquivo sem mexer na sua cópia de trabalho.', 'コミット一つをメッセージと差分ごと表示します。<commit>:<path>の形で書けば、作業中のファイルに触れずに昔の中身だけ取り出せます。', 'Zeigt einen Commit mit Nachricht und Diff; die Form <commit>:<pfad> holt eine alte Fassung der Datei, ohne die Arbeitskopie anzurühren.', "Affiche un commit avec son message et son diff ; la forme <commit>:<chemin> extrait une ancienne version du fichier sans toucher à la copie de travail.", 'एक commit को उसके संदेश और diff के साथ दिखाता है; <commit>:<path> लिखने पर फ़ाइल का पुराना रूप working copy छेड़े बिना निकल आता है।', '把一个提交的说明和改动一起打印出来；写成 <commit>:<path> 就能取出文件的旧内容而不动你的工作副本。', '把一個提交的訊息和改動一起印出來；寫成 <commit>:<path> 就能取出檔案的舊內容而不動你的工作副本。'],
  'git-blame': ['한 줄 한 줄 마지막으로 고친 커밋을 붙여 보여줍니다 — 서식만 바꾼 커밋이 진짜 저자를 가리므로 -w와 --ignore-rev가 있습니다.', 'Marks each line with the commit that last changed it; a pure reformat hides the real author, which is what -w and --ignore-rev are for.', 'Marca cada línea con el commit que la cambió por última vez; un reformateo oculta al autor real, y para eso están -w y --ignore-rev.', 'Marca cada linha com o commit que a alterou por último; uma reformatação esconde o autor real, e é para isso que servem -w e --ignore-rev.', '一行ごとに最後に変えたコミットを添えて見せます。整形だけのコミットが本当の作者を隠すので、-wや--ignore-revを使います。', 'Versieht jede Zeile mit dem Commit, der sie zuletzt geändert hat; eine reine Umformatierung verdeckt den echten Autor — dafür gibt es -w und --ignore-rev.', "Attribue à chaque ligne le commit qui l'a modifiée en dernier ; un simple reformatage masque le véritable auteur, d'où -w et --ignore-rev.", 'हर पंक्ति के साथ वह commit दिखाता है जिसने उसे अंत में बदला; सिर्फ़ formatting वाला commit असली लेखक छिपा देता है, इसीलिए -w और --ignore-rev हैं।', '给每一行标出最后改动它的提交；只做格式化的提交会盖住真正的作者，这就是 -w 和 --ignore-rev 的用处。', '為每一行標出最後改動它的提交；只做格式化的提交會蓋住真正的作者，這就是 -w 和 --ignore-rev 的用處。'],

  /* ───────── git — 브랜치 ───────── */
  'git-branch': ['브랜치를 나열하고 만들고 지웁니다 — 지워도 원격에는 그대로 남아 서버에서 없애려면 git push origin --delete가 따로 필요합니다.', 'Lists, creates and deletes branches locally; deleting one leaves the remote copy alone, so the server still needs git push origin --delete.', 'Lista, crea y borra ramas en local; borrar una no toca la del remoto, el servidor aún necesita git push origin --delete.', 'Lista, cria e apaga branches localmente; apagar um não mexe no remoto, o servidor ainda pede git push origin --delete.', 'ブランチを並べ、作り、消します。消してもリモートには残るので、サーバー側はgit push origin --deleteが別に必要です。', 'Listet, erstellt und löscht Branches lokal; ein gelöschter Branch bleibt auf dem Remote bestehen, dort braucht es git push origin --delete.', "Liste, crée et supprime des branches en local ; la supprimer ne touche pas le distant, le serveur exige git push origin --delete.", 'branch सूचीबद्ध करता, बनाता और स्थानीय रूप से मिटाता है; मिटाने पर remote की प्रति बची रहती है, सर्वर के लिए git push origin --delete अलग से चाहिए।', '在本地列出、创建和删除分支；删掉本地的不会动远端，服务器那边还要 git push origin --delete。', '在本機列出、建立和刪除分支；刪掉本機的不會動遠端，伺服器那邊還要 git push origin --delete。'],
  'git-checkout': ['브랜치를 옮기고 파일도 되돌리는 옛 명령으로, git 2.23에서 switch와 restore로 갈라졌습니다 — checkout -- <file>은 커밋하지 않은 수정을 되찾을 수 없게 지웁니다.', 'The old command for both switching branches and restoring files, split into switch and restore in git 2.23; checkout -- <file> erases uncommitted edits for good.', 'El comando antiguo que cambia de rama y restaura archivos, dividido en switch y restore en git 2.23; checkout -- <archivo> borra para siempre los cambios sin commit.', 'O comando antigo que troca de branch e restaura arquivos, dividido em switch e restore no git 2.23; checkout -- <arquivo> apaga de vez as edições não commitadas.', 'ブランチの移動とファイルの復元を兼ねた古い命令で、git 2.23でswitchとrestoreに分かれました。checkout -- <file>はコミットしていない修正を取り返せない形で消します。', 'Der alte Befehl für Branch-Wechsel und Datei-Wiederherstellung, in git 2.23 in switch und restore geteilt; checkout -- <datei> löscht nicht committete Änderungen endgültig.', "L'ancienne commande qui change de branche et restaure des fichiers, scindée en switch et restore dans git 2.23 ; checkout -- <fichier> efface définitivement les modifications non commitées.", 'branch बदलने और फ़ाइल लौटाने वाला पुराना आदेश, जो git 2.23 में switch और restore में बँट गया; checkout -- <file> बिना commit किए बदलाव हमेशा के लिए मिटा देता है।', '既能切分支又能还原文件的旧命令，在 git 2.23 里拆成了 switch 和 restore；checkout -- <file> 会把未提交的改动彻底删掉。', '既能切分支又能還原檔案的舊命令，在 git 2.23 裡拆成了 switch 和 restore；checkout -- <file> 會把未提交的改動徹底刪掉。'],
  'git-switch': ['브랜치를 옮기는 일만 하는 git 2.23의 명령입니다 — 파일 내용을 되돌리는 일은 하지 않으니 그건 restore가 맡습니다.', 'The git 2.23 command that only moves between branches; it never rewrites file contents, which is what restore is for.', 'El comando de git 2.23 que solo cambia de rama; nunca reescribe el contenido de los archivos, para eso está restore.', 'O comando do git 2.23 que apenas troca de branch; nunca reescreve o conteúdo dos arquivos, isso é papel do restore.', 'ブランチの移動だけを担うgit 2.23の命令です。ファイルの中身を書き戻すことはせず、それはrestoreの役目です。', 'Der Befehl aus git 2.23, der ausschließlich Branches wechselt; Dateiinhalte schreibt er nie zurück, dafür ist restore da.', "La commande de git 2.23 qui ne fait que changer de branche ; elle ne réécrit jamais le contenu des fichiers, c'est le rôle de restore.", 'git 2.23 का आदेश जो सिर्फ़ branch बदलता है; फ़ाइलों की सामग्री कभी नहीं लौटाता, वह काम restore का है।', 'git 2.23 引入的命令，只负责在分支之间切换；它从不改写文件内容，那是 restore 的事。', 'git 2.23 引入的命令，只負責在分支之間切換；它從不改寫檔案內容，那是 restore 的事。'],
  'git-restore': ['파일 내용을 되돌리는 git 2.23의 명령입니다 — 기본값은 작업 파일을 덮어써 커밋하지 않은 수정이 사라지고, --staged는 스테이지에서만 내립니다.', 'The git 2.23 command for putting file contents back; by default it overwrites your working file and the uncommitted edits are gone, while --staged only unstages.', 'El comando de git 2.23 para devolver el contenido de un archivo; por defecto sobrescribe tu archivo y los cambios sin commit desaparecen, mientras --staged solo quita del área de preparación.', 'O comando do git 2.23 para devolver o conteúdo de um arquivo; por padrão sobrescreve o arquivo e as edições não commitadas somem, enquanto --staged só tira da área de preparação.', 'ファイルの中身を戻すgit 2.23の命令です。既定では作業中のファイルを上書きしてコミットしていない修正が消え、--stagedならステージから外すだけです。', 'Der Befehl aus git 2.23, der Dateiinhalte zurücksetzt; standardmäßig überschreibt er die Arbeitsdatei und nicht committete Änderungen sind weg, --staged nimmt nur aus der Staging-Area.', "La commande de git 2.23 qui restaure le contenu des fichiers ; par défaut elle écrase votre fichier et les modifications non commitées disparaissent, alors que --staged se contente de désindexer.", 'फ़ाइल की सामग्री लौटाने वाला git 2.23 का आदेश; डिफ़ॉल्ट रूप से यह working फ़ाइल को ऊपर लिख देता है और बिना commit बदलाव चले जाते हैं, जबकि --staged सिर्फ़ unstage करता है।', 'git 2.23 引入的命令，用来还原文件内容；默认会覆盖工作区的文件，未提交的改动就没了，而 --staged 只是取消暂存。', 'git 2.23 引入的命令，用來還原檔案內容；預設會覆蓋工作區的檔案，未提交的改動就沒了，而 --staged 只是取消暫存。'],

  /* ───────── git — 합치기와 되돌리기 ───────── */
  'git-merge': ['다른 브랜치의 작업을 지금 브랜치로 합칩니다 — --squash는 합침 기록을 남기지 않아 그 브랜치가 나중에도 합쳐지지 않은 것으로 보입니다.', 'Brings the work of another branch into the current one; --squash records no merge, so git still counts that branch as unmerged afterwards.', 'Trae el trabajo de otra rama a la actual; --squash no registra una fusión, así que git sigue considerando esa rama sin fusionar.', 'Traz o trabalho de outro branch para o atual; --squash não registra uma mesclagem, então o git continua vendo aquele branch como não mesclado.', '別のブランチの作業を今のブランチに取り込みます。--squashは合流の記録を残さないので、そのブランチは後からも未マージ扱いのままです。', 'Holt die Arbeit eines anderen Branches in den aktuellen; --squash zeichnet keinen Merge auf, git hält den Branch danach weiter für nicht gemergt.', "Intègre le travail d'une autre branche dans la branche courante ; --squash n'enregistre aucune fusion, git considère donc toujours cette branche comme non fusionnée.", 'दूसरी branch का काम मौजूदा branch में मिला देता है; --squash कोई merge दर्ज नहीं करता, इसलिए git उस branch को बाद में भी unmerged मानता रहता है।', '把另一个分支的工作并进当前分支；--squash 不会留下合并记录，所以之后 git 仍然认为那个分支没被合并。', '把另一個分支的工作併進目前分支；--squash 不會留下合併記錄，所以之後 git 仍然認為那個分支沒被合併。'],
  'git-rebase': ['내 커밋을 다른 기준 위에 다시 얹습니다 — 해시가 새로 생기므로 남이 이미 받아 간 브랜치에는 rebase하지 않고 merge를 씁니다.', 'Replays your commits on a new base; the hashes change, so never rebase a branch other people already pulled — merge there instead.', 'Reaplica tus commits sobre otra base; los hashes cambian, así que nunca rebases una rama que otros ya descargaron: allí se usa merge.', 'Reaplica seus commits sobre outra base; os hashes mudam, então nunca faça rebase de um branch que outras pessoas já baixaram — ali se usa merge.', '自分のコミットを別の土台の上に付け替えます。ハッシュが変わるので、他の人がすでに取得したブランチにはrebaseせずmergeを使います。', 'Spielt Ihre Commits auf einer neuen Basis erneut ab; die Hashes ändern sich, also niemals einen Branch rebasen, den andere schon geholt haben — dort mergen.', "Rejoue vos commits sur une nouvelle base ; les hachages changent, donc ne rebasez jamais une branche déjà récupérée par d'autres : utilisez merge.", 'आपके commit को नई नींव पर फिर से रखता है; hash बदल जाते हैं, इसलिए जिस branch को दूसरे पहले ही खींच चुके हैं उसे rebase न करें — वहाँ merge करें।', '把你的提交重新放到另一个基点上；哈希会变，所以别对别人已经拉走的分支做 rebase，那种情况用 merge。', '把你的提交重新放到另一個基點上；雜湊會變，所以別對別人已經拉走的分支做 rebase，那種情況用 merge。'],
  'git-reset': ['브랜치가 가리키는 커밋을 옮깁니다 — --soft는 변경을 스테이지에 남기고, --mixed(기본)는 스테이지만 풀어 수정은 파일에 두며, --hard는 파일의 수정까지 함께 버려 되찾을 수 없습니다.', 'Moves the branch pointer to another commit: --soft keeps everything staged, --mixed (the default) also clears the staging area but leaves your edits in the files, and --hard throws those edits away too, unrecoverably.', 'Mueve el puntero de la rama a otro commit: --soft deja todo preparado, --mixed (por defecto) además vacía el área de preparación pero conserva tus cambios en los archivos, y --hard también los destruye sin recuperación.', 'Move o ponteiro do branch para outro commit: --soft mantém tudo preparado, --mixed (padrão) também limpa a área de preparação mas deixa suas edições nos arquivos, e --hard descarta essas edições junto, sem volta.', 'ブランチが指すコミットを移します。--softは変更をステージに残し、--mixed(既定)はステージを外して修正はファイルに残し、--hardはその修正まで捨てて取り返せません。', 'Verschiebt den Branch-Zeiger auf einen anderen Commit: --soft lässt alles vorbereitet, --mixed (Standard) leert zusätzlich die Staging-Area, behält die Änderungen aber in den Dateien, und --hard verwirft auch diese unwiederbringlich.', "Déplace le pointeur de branche sur un autre commit : --soft garde tout indexé, --mixed (par défaut) vide aussi l'index mais laisse vos modifications dans les fichiers, et --hard les détruit également, sans retour.", 'branch के pointer को दूसरे commit पर ले जाता है: --soft सब कुछ staged छोड़ता है, --mixed (डिफ़ॉल्ट) staging भी खाली करता है पर बदलाव फ़ाइलों में रहते हैं, और --hard उन बदलावों को भी हमेशा के लिए मिटा देता है।', '把分支指针移到别的提交：--soft 让改动全留在暂存区，--mixed（默认）连暂存区一起清掉但改动还在文件里，--hard 连文件里的改动也一起丢掉，找不回来。', '把分支指標移到別的提交：--soft 讓改動全留在暫存區，--mixed（預設）連暫存區一起清掉但改動還在檔案裡，--hard 連檔案裡的改動也一起丟掉，找不回來。'],
  'git-revert': ['되돌리는 변경을 새 커밋으로 덧붙입니다 — 이력을 지우지 않는다는 점이 포인터를 옮기는 reset과의 차이라, 이미 올린 커밋은 revert로 되돌립니다.', 'Undoes a commit by adding a new opposite commit; it leaves history intact, unlike reset which moves the branch pointer, so anything already pushed should be reverted.', 'Deshace un commit añadiendo otro commit contrario; no borra la historia, a diferencia de reset que mueve el puntero, así que lo ya publicado se deshace con revert.', 'Desfaz um commit acrescentando outro commit contrário; não apaga o histórico, ao contrário do reset que move o ponteiro, então o que já foi enviado se desfaz com revert.', '打ち消す変更を新しいコミットとして足します。履歴を消さない点がポインタを動かすresetとの違いで、すでにpushしたものはrevertで戻します。', 'Nimmt einen Commit zurück, indem ein gegenläufiger Commit hinzukommt; die Historie bleibt erhalten — anders als bei reset, das den Zeiger verschiebt — deshalb wird Gepushtes revertiert.', "Annule un commit en ajoutant un commit inverse ; l'historique reste intact, contrairement à reset qui déplace le pointeur, donc ce qui est déjà poussé se défait avec revert.", 'किसी commit को उलटने वाला नया commit जोड़कर उसे रद्द करता है; इतिहास मिटता नहीं, जबकि reset pointer सरकाता है — इसलिए push हो चुके काम को revert से लौटाएँ।', '通过新增一个相反的提交来撤销旧提交；它不删历史，这正是它和移动指针的 reset 的区别，已经推上去的提交要用 revert。', '透過新增一個相反的提交來撤銷舊提交；它不刪歷史，這正是它和移動指標的 reset 的差別，已經推上去的提交要用 revert。'],
  'git-cherry-pick': ['다른 브랜치의 커밋 하나를 지금 브랜치에 복사합니다 — 해시가 새로 생기므로 나중에 그 브랜치를 merge하면 같은 변경이 두 번 보일 수 있습니다.', 'Copies a single commit onto the current branch as a new commit with a new hash, so merging that branch later can show the same change twice.', 'Copia un solo commit a la rama actual como un commit nuevo con otro hash, por lo que al fusionar esa rama luego el mismo cambio puede aparecer dos veces.', 'Copia um único commit para o branch atual como um commit novo com outro hash, então mesclar aquele branch depois pode mostrar a mesma mudança duas vezes.', '他のブランチのコミット一つを今のブランチへ複製します。新しいハッシュになるため、後でそのブランチをmergeすると同じ変更が二度現れることがあります。', 'Kopiert einen einzelnen Commit als neuen Commit mit neuem Hash in den aktuellen Branch; mergt man den Branch später, kann dieselbe Änderung doppelt erscheinen.', "Copie un seul commit sur la branche courante sous un nouveau hachage ; fusionner cette branche plus tard peut donc faire apparaître deux fois la même modification.", 'किसी एक commit को नए hash के साथ मौजूदा branch पर कॉपी करता है, इसलिए बाद में उस branch को merge करने पर वही बदलाव दो बार दिख सकता है।', '把某一个提交以新的哈希复制到当前分支；之后再合并那个分支时，同一处改动可能出现两次。', '把某一個提交以新的雜湊複製到目前分支；之後再合併那個分支時，同一處改動可能出現兩次。'],
  'git-stash': ['고치던 것을 잠시 치워 두고 깨끗한 상태로 돌아갑니다 — 기본으로는 추적되지 않은 파일이 그대로 남으니 -u를 붙이고, pop은 꺼내면서 목록에서 지우고 apply는 남깁니다.', 'Parks your unfinished changes and gives you a clean tree; untracked files stay behind unless you pass -u, and pop removes the entry while apply keeps it.', 'Aparta los cambios sin terminar y te deja el árbol limpio; los archivos sin rastrear se quedan salvo con -u, y pop borra la entrada mientras apply la conserva.', 'Guarda as mudanças inacabadas e devolve a árvore limpa; arquivos sem rastreio ficam para trás a menos que use -u, e pop apaga a entrada enquanto apply a mantém.', '途中の変更を一時的にしまい、きれいな状態に戻します。既定では追跡外のファイルが残るので-uを付け、popは取り出して一覧から消し、applyは残します。', 'Legt unfertige Änderungen beiseite und hinterlässt einen sauberen Baum; unverfolgte Dateien bleiben ohne -u zurück, und pop löscht den Eintrag, apply behält ihn.', "Met de côté vos modifications en cours et rend l'arbre propre ; les fichiers non suivis restent sauf avec -u, et pop supprime l'entrée là où apply la conserve.", 'अधूरे बदलाव किनारे रखकर पेड़ साफ़ कर देता है; untracked फ़ाइलें -u के बिना पीछे छूट जाती हैं, और pop प्रविष्टि हटा देता है जबकि apply उसे रखता है।', '把没做完的改动先收起来，让工作区变干净；不加 -u 时未跟踪文件会留在原地，pop 取出后会删掉那条记录，apply 则保留。', '把沒做完的改動先收起來，讓工作區變乾淨；不加 -u 時未追蹤檔案會留在原地，pop 取出後會刪掉那筆記錄，apply 則保留。'],
  'git-clean': ['추적되지 않은 파일을 지웁니다 — git이 사본을 가진 적이 없어 되살릴 수 없고, -fdx는 .env처럼 무시 목록에 있던 파일까지 지우니 먼저 -n으로 확인합니다.', 'Deletes untracked files, which git never had a copy of, so nothing comes back; -fdx also wipes ignored files such as a local .env, so run -n first.', 'Borra archivos sin rastrear, de los que git nunca tuvo copia, así que no vuelven; -fdx además elimina los ignorados como un .env local, ejecuta -n antes.', 'Apaga arquivos sem rastreio, dos quais o git nunca teve cópia, então nada volta; -fdx também remove ignorados como um .env local, rode -n antes.', '追跡外のファイルを削除します。gitが控えを持っていないので戻せず、-fdxは.envのような無視ファイルまで消すため、先に-nで確かめます。', 'Löscht unverfolgte Dateien, von denen git nie eine Kopie hatte — nichts kommt zurück; -fdx entfernt zusätzlich ignorierte Dateien wie eine lokale .env, also vorher -n ausführen.', "Supprime les fichiers non suivis, dont git n'a jamais eu de copie : rien ne revient ; -fdx efface aussi les fichiers ignorés comme un .env local, faites d'abord -n.", 'untracked फ़ाइलें मिटा देता है, जिनकी git के पास कभी प्रति नहीं थी, सो कुछ वापस नहीं आता; -fdx स्थानीय .env जैसी ignored फ़ाइलें भी हटाता है, पहले -n चलाएँ।', '删除未跟踪的文件；git 从未保存过它们，删了就回不来，-fdx 连本地 .env 这类被忽略的文件也一起清掉，先跑一次 -n。', '刪除未追蹤的檔案；git 從未保存過它們，刪了就回不來，-fdx 連本機 .env 這類被忽略的檔案也一起清掉，先跑一次 -n。'],

  /* ───────── git — 원격 ───────── */
  'git-remote': ['원격 저장소의 이름과 주소를 다룹니다 — 적어 두는 일뿐이라 add나 set-url을 해도 fetch·push를 하기 전에는 아무것도 오가지 않습니다.', 'Manages the names and URLs of remote repositories; it only records them, so nothing travels until you actually fetch or push.', 'Gestiona los nombres y las URL de los repositorios remotos; solo los apunta, nada viaja hasta que haces fetch o push.', 'Gerencia os nomes e as URLs dos repositórios remotos; só anota, nada trafega até você fazer fetch ou push.', 'リモートリポジトリの名前と場所を扱います。記録するだけなので、addやset-urlをしてもfetchやpushをするまで何も行き来しません。', 'Verwaltet Namen und URLs entfernter Repositories; es notiert sie nur, es fließt nichts, bis Sie fetchen oder pushen.', "Gère les noms et les URL des dépôts distants ; il ne fait que les noter, rien ne circule avant un fetch ou un push.", 'रिमोट repository के नाम और URL सँभालता है; यह उन्हें केवल दर्ज करता है, fetch या push करने तक कुछ आता-जाता नहीं।', '管理远端仓库的名字和地址；它只是记下来，在你真正 fetch 或 push 之前什么都不会传输。', '管理遠端儲存庫的名稱和位址；它只是記下來，在你真正 fetch 或 push 之前什麼都不會傳輸。'],
  'git-fetch': ['원격의 새 커밋을 받아 두기만 합니다 — 내 파일과 브랜치는 그대로라 merge나 rebase를 해야 반영되고, 서버에서 지운 브랜치는 --prune 전까지 남아 있습니다.', 'Downloads new commits without touching your files or branch, so a merge or rebase still has to follow, and branches deleted on the server linger until --prune.', 'Descarga los commits nuevos sin tocar tus archivos ni tu rama, así que aún falta un merge o rebase, y las ramas borradas en el servidor siguen ahí hasta --prune.', 'Baixa os commits novos sem tocar nos seus arquivos nem no seu branch, então ainda falta um merge ou rebase, e branches apagados no servidor continuam listados até --prune.', 'リモートの新しいコミットを受け取るだけで、自分のファイルやブランチは動きません。反映にはmergeやrebaseが必要で、サーバーで消えたブランチは--pruneまで残ります。', 'Lädt neue Commits herunter, ohne Ihre Dateien oder Ihren Branch anzurühren; ein Merge oder Rebase muss folgen, und auf dem Server gelöschte Branches bleiben bis --prune sichtbar.', "Télécharge les nouveaux commits sans toucher à vos fichiers ni à votre branche : un merge ou un rebase doit suivre, et les branches supprimées côté serveur subsistent jusqu'à --prune.", 'नए commit उतार लेता है पर आपकी फ़ाइलों और branch को नहीं छूता, इसलिए merge या rebase बाद में करना पड़ता है, और सर्वर पर मिटी branch --prune तक दिखती रहती है।', '只把远端的新提交取下来，不动你的文件和分支，要生效还得 merge 或 rebase；服务器上已删的分支在 --prune 之前还会留着。', '只把遠端的新提交取下來，不動你的檔案和分支，要生效還得 merge 或 rebase；伺服器上已刪的分支在 --prune 之前還會留著。'],
  'git-pull': ['fetch와 merge를 한 번에 합니다 — 그래서 뜻하지 않은 merge 커밋이 생기고, --rebase나 --ff-only를 쓰면 막을 수 있습니다.', 'Runs fetch and merge in one step, which is where surprise merge commits come from; --rebase or --ff-only prevents them.', 'Ejecuta fetch y merge de una vez, de ahí vienen los commits de fusión inesperados; --rebase o --ff-only lo evita.', 'Executa fetch e merge de uma vez, e daí vêm os commits de mesclagem inesperados; --rebase ou --ff-only evita isso.', 'fetchとmergeを一度に行います。だから思わぬマージコミットができるので、--rebaseや--ff-onlyで防ぎます。', 'Führt fetch und merge in einem Schritt aus — daher die überraschenden Merge-Commits; --rebase oder --ff-only verhindert sie.', "Enchaîne fetch et merge, d'où les commits de fusion inattendus ; --rebase ou --ff-only les évite.", 'fetch और merge को एक ही बार में करता है, यहीं से अनचाहे merge commit आते हैं; --rebase या --ff-only उन्हें रोकता है।', '把 fetch 和 merge 一次做完，这正是那些意外合并提交的来源；用 --rebase 或 --ff-only 可以避免。', '把 fetch 和 merge 一次做完，這正是那些意外合併提交的來源；用 --rebase 或 --ff-only 可以避免。'],
  'git-push': ['내 커밋을 원격으로 올립니다 — --force는 원격 브랜치를 덮어써 남이 올린 커밋까지 지울 수 있으니, 원격이 움직였으면 거절하는 --force-with-lease를 씁니다.', 'Sends your commits to a remote; --force overwrites the remote branch and can erase commits other people pushed, so use --force-with-lease, which refuses when the remote moved.', 'Envía tus commits a un remoto; --force sobrescribe la rama remota y puede borrar commits de otros, así que usa --force-with-lease, que se niega si el remoto cambió.', 'Envia seus commits para um remoto; --force sobrescreve o branch remoto e pode apagar commits de outras pessoas, então use --force-with-lease, que recusa se o remoto andou.', '自分のコミットをリモートへ送ります。--forceはリモートのブランチを上書きして他人のコミットまで消しかねないので、リモートが動いていたら拒否する--force-with-leaseを使います。', 'Schickt Ihre Commits zu einem Remote; --force überschreibt den Remote-Branch und kann Commits anderer löschen, nutzen Sie daher --force-with-lease, das bei bewegtem Remote abbricht.', "Envoie vos commits vers un dépôt distant ; --force écrase la branche distante et peut effacer les commits des autres, préférez --force-with-lease, qui refuse si le distant a bougé.", 'आपके commit remote पर भेजता है; --force remote branch को ऊपर लिख देता है और दूसरों के commit तक मिटा सकता है, इसलिए --force-with-lease लगाएँ, जो remote बदल गया हो तो मना कर देता है।', '把你的提交推到远端；--force 会覆盖远端分支，连别人推的提交都可能被抹掉，所以用 --force-with-lease，远端一动它就拒绝。', '把你的提交推到遠端；--force 會覆蓋遠端分支，連別人推的提交都可能被抹掉，所以用 --force-with-lease，遠端一動它就拒絕。'],
  'git-tag': ['커밋에 버전 같은 이름표를 붙입니다 — git push만으로는 태그가 올라가지 않아 태그 이름을 따로 밀어야 합니다.', 'Puts a name such as a version on a commit; a plain git push does not carry tags, so the tag has to be pushed by name.', 'Pone un nombre, como una versión, en un commit; un git push normal no lleva las etiquetas, hay que empujar la etiqueta por su nombre.', 'Coloca um nome, como uma versão, em um commit; um git push comum não leva as tags, é preciso enviar a tag pelo nome.', 'コミットにバージョンのような名札を付けます。git pushだけではタグは送られないので、タグ名を指定して別に押します。', 'Hängt einem Commit einen Namen wie eine Versionsnummer an; ein einfaches git push nimmt Tags nicht mit, der Tag muss namentlich gepusht werden.', "Attache à un commit un nom, par exemple une version ; un git push ordinaire n'emporte pas les étiquettes, il faut pousser l'étiquette par son nom.", 'किसी commit पर version जैसा नाम लगा देता है; सादा git push tag नहीं भेजता, tag को नाम से अलग push करना पड़ता है।', '给某个提交贴上版本之类的名字；普通的 git push 不会带上标签，得按名字单独推。', '給某個提交貼上版本之類的名字；普通的 git push 不會帶上標籤，得按名字單獨推。'],

  /* ───────── git — 파일 다루기 ───────── */
  'git-rm': ['파일을 색인과 디스크에서 함께 지웁니다 — --cached는 파일을 남기고 추적만 끊지만, 이미 커밋된 내용은 이력에 그대로 있어 유출된 비밀은 사라지지 않습니다.', 'Removes a file from the index and from disk; --cached keeps the file and only stops tracking, but the old content stays in history, so a leaked secret is still there.', 'Quita un archivo del índice y del disco; --cached lo conserva y solo deja de rastrearlo, pero el contenido antiguo permanece en la historia, así que un secreto filtrado sigue ahí.', 'Remove um arquivo do índice e do disco; --cached mantém o arquivo e só para de rastreá-lo, mas o conteúdo antigo fica no histórico, então um segredo vazado continua lá.', 'ファイルを索引とディスクの両方から消します。--cachedはファイルを残して追跡だけ止めますが、過去の中身は履歴に残るので漏れた秘密は消えません。', 'Entfernt eine Datei aus dem Index und von der Platte; --cached behält die Datei und beendet nur die Verfolgung, doch der alte Inhalt bleibt in der Historie — ein geleaktes Geheimnis ist weiterhin da.', "Retire un fichier de l'index et du disque ; --cached conserve le fichier et cesse seulement de le suivre, mais l'ancien contenu reste dans l'historique, donc un secret fuité y demeure.", 'फ़ाइल को index और डिस्क दोनों से हटाता है; --cached फ़ाइल रखता है और सिर्फ़ ट्रैकिंग रोकता है, पर पुरानी सामग्री इतिहास में बनी रहती है, इसलिए लीक हुआ secret वहीं रहता है।', '把文件从索引和磁盘上一起删掉；--cached 会保留文件、只停止跟踪，但旧内容仍留在历史里，泄露的密钥并不会因此消失。', '把檔案從索引和磁碟上一起刪掉；--cached 會保留檔案、只停止追蹤，但舊內容仍留在歷史裡，洩漏的密鑰並不會因此消失。'],
  'git-mv': ['파일을 옮기면서 그 사실을 바로 스테이지에 올립니다 — git은 이름 바꿈을 따로 저장하지 않고 내용이 닮은 것을 보고 추측하니, 대소문자만 바꾸는 이름은 macOS와 윈도에서 -f가 필요합니다.', 'Moves a file and stages the move in one step; git stores no rename, it guesses one from similar content, so a case-only rename needs -f on macOS and Windows.', 'Mueve un archivo y prepara el cambio en un paso; git no guarda renombrados, los deduce por la similitud del contenido, y un cambio solo de mayúsculas necesita -f en macOS y Windows.', 'Move um arquivo e prepara a mudança de uma vez; o git não guarda renomeações, ele as deduz pelo conteúdo parecido, e uma troca só de maiúsculas precisa de -f no macOS e no Windows.', 'ファイルを移動して、その事実をそのままステージに載せます。gitは改名を保存せず内容の似かたから推測するので、大文字小文字だけ変える改名はmacOSやWindowsで-fが必要です。', 'Verschiebt eine Datei und nimmt die Änderung gleich mit auf; git speichert keine Umbenennung, sondern erkennt sie an ähnlichem Inhalt — eine Umbenennung nur der Groß- und Kleinschreibung braucht unter macOS und Windows -f.', "Déplace un fichier et indexe le changement d'un coup ; git n'enregistre pas les renommages, il les déduit du contenu, donc un changement de casse seul exige -f sous macOS et Windows.", 'फ़ाइल हटाकर दूसरी जगह रखता है और उसी क़दम में stage भी कर देता है; git rename सहेजता नहीं, मिलते-जुलते content से अनुमान लगाता है, इसलिए सिर्फ़ केस बदलने पर macOS और Windows में -f चाहिए।', '移动文件并顺手把这次改动放进暂存区；git 不保存重命名，而是靠内容相似度推断，所以只改大小写的重命名在 macOS 和 Windows 上需要 -f。', '移動檔案並順手把這次改動放進暫存區；git 不儲存重新命名，而是靠內容相似度推斷，所以只改大小寫的更名在 macOS 和 Windows 上需要 -f。'],
  'git-ls-files': ['디스크가 아니라 색인에 든 경로를 나열합니다 — 스크립트로 추적 파일을 훑을 때 믿을 수 있는 목록이고, -i는 혼자 쓰지 못해 -c나 -o와 --exclude-standard를 함께 적어야 합니다.', 'Lists paths from the index rather than from disk, which makes it the reliable list to script over; -i cannot stand alone and needs -c or -o plus --exclude-standard.', 'Lista rutas del índice, no del disco, y por eso es la lista fiable para un script; -i no funciona solo y exige -c u -o junto con --exclude-standard.', 'Lista caminhos do índice, não do disco, e é por isso a lista confiável para scripts; -i não funciona sozinho e exige -c ou -o mais --exclude-standard.', 'ディスクではなく索引に入っている経路を並べます。スクリプトで追跡ファイルを回すのに確実な一覧で、-iは単独では使えず-cか-oと--exclude-standardが要ります。', 'Listet Pfade aus dem Index statt von der Platte und ist damit die verlässliche Liste für Skripte; -i geht nicht allein, es braucht -c oder -o samt --exclude-standard.', "Liste les chemins de l'index et non du disque, ce qui en fait la liste fiable pour un script ; -i ne s'emploie pas seul et réclame -c ou -o avec --exclude-standard.", 'डिस्क की जगह index में दर्ज पथ सूचीबद्ध करता है, इसलिए script के लिए यही भरोसेमंद सूची है; -i अकेले नहीं चलता, उसके साथ -c या -o और --exclude-standard चाहिए।', '列出索引里的路径而不是磁盘上的文件，所以脚本遍历已跟踪文件时靠它最稳；-i 不能单独用，必须配 -c 或 -o 再加 --exclude-standard。', '列出索引裡的路徑而不是磁碟上的檔案，所以指令稿要走訪已追蹤檔案時靠它最穩；-i 不能單獨用，必須配 -c 或 -o 再加 --exclude-standard。'],
  'git-update-index': ['색인을 직접 손봅니다 — 이 표시는 내 컴퓨터에만 남고 push되지 않으며, 추적 중인 설정 파일에 내 수정을 남겨 두는 것은 --assume-unchanged가 아니라 --skip-worktree입니다.', 'Edits the index directly; the marks are local and never pushed, and the one that keeps your local edits to a tracked config file is --skip-worktree, not --assume-unchanged.', 'Modifica el índice directamente; las marcas son locales y nunca se envían, y la que conserva tus cambios locales en un archivo de configuración es --skip-worktree, no --assume-unchanged.', 'Altera o índice diretamente; as marcas são locais e nunca vão no push, e a que preserva suas edições locais em um arquivo de configuração é --skip-worktree, não --assume-unchanged.', '索引を直接いじります。この印はローカル限りでpushされず、追跡中の設定ファイルに自分の変更を残したいときは--assume-unchangedではなく--skip-worktreeです。', 'Bearbeitet den Index direkt; die Markierungen sind lokal und werden nie gepusht, und für eigene Änderungen an einer verfolgten Konfigurationsdatei ist --skip-worktree zuständig, nicht --assume-unchanged.', "Modifie l'index directement ; ces marques restent locales et ne sont jamais poussées, et celle qui préserve vos modifications d'un fichier de configuration suivi est --skip-worktree, pas --assume-unchanged.", 'index को सीधे बदलता है; ये निशान स्थानीय होते हैं और कभी push नहीं होते, और ट्रैक हो रही config फ़ाइल में अपने बदलाव बचाने वाला विकल्प --skip-worktree है, --assume-unchanged नहीं।', '直接改动索引；这些标记只在本地、不会被推送，而想保留自己对已跟踪配置文件的改动，该用 --skip-worktree 而不是 --assume-unchanged。', '直接改動索引；這些標記只在本機、不會被推送，而想保留自己對已追蹤設定檔的改動，該用 --skip-worktree 而不是 --assume-unchanged。'],
  'git-sparse-checkout': ['git 2.25에 들어온 명령으로, 큰 저장소에서 지정한 폴더만 디스크에 둡니다 — 이력은 그대로 다 있고, cone 모드는 글롭이 아니라 폴더 이름을 받습니다.', 'Added in git 2.25, it keeps only the directories you name on disk; the history is still complete and cone mode takes directory names, not glob patterns.', 'Añadido en git 2.25, mantiene en disco solo los directorios que nombras; la historia sigue completa y el modo cone acepta nombres de directorio, no patrones glob.', 'Adicionado no git 2.25, mantém em disco só os diretórios que você nomeia; o histórico continua completo e o modo cone aceita nomes de diretório, não padrões glob.', 'git 2.25で入った命令で、大きなリポジトリのうち指定したフォルダーだけをディスクに置きます。履歴は丸ごとあり、coneモードはグロブではなくフォルダー名を取ります。', 'In git 2.25 eingeführt, behält es nur die genannten Verzeichnisse auf der Platte; die Historie bleibt vollständig, und der Cone-Modus erwartet Verzeichnisnamen, keine Glob-Muster.', "Apparue dans git 2.25, elle ne garde sur le disque que les répertoires nommés ; l'historique reste entier et le mode cone attend des noms de répertoires, pas des motifs glob.", 'git 2.25 में जुड़ा यह आदेश बड़े repository में सिर्फ़ बताए गए फ़ोल्डर डिस्क पर रखता है; इतिहास पूरा ही रहता है और cone mode glob नहीं, फ़ोल्डर के नाम लेता है।', 'git 2.25 加入的命令，只把你指定的目录留在磁盘上；历史仍是完整的，cone 模式接受目录名而不是 glob 通配符。', 'git 2.25 加入的命令，只把你指定的目錄留在磁碟上；歷史仍是完整的，cone 模式接受目錄名而不是 glob 萬用字元。'],

  /* ───────── git — 찾기와 고치기 ───────── */
  'git-reflog': ['HEAD와 브랜치가 지나온 자리를 기록해 둡니다 — reset --hard나 브랜치 삭제로 잃은 커밋을 여기서 찾지만, 기록은 기본 90일이면 만료되고 내 컴퓨터에만 있습니다.', 'Remembers every position HEAD and your branches have had, which is where commits lost to reset --hard or a deleted branch turn up; entries expire after 90 days by default and exist only on your machine.', 'Recuerda todas las posiciones que han tenido HEAD y tus ramas, y ahí aparecen los commits perdidos por reset --hard o una rama borrada; las entradas caducan a los 90 días y solo existen en tu máquina.', 'Guarda todas as posições que HEAD e seus branches tiveram, e é ali que reaparecem commits perdidos por reset --hard ou por um branch apagado; as entradas expiram em 90 dias e só existem na sua máquina.', 'HEADとブランチが通ってきた位置を記録します。reset --hardやブランチ削除で失ったコミットはここで見つかりますが、既定で90日で期限切れになり、この記録は自分の手元にしかありません。', 'Merkt sich jede Position von HEAD und Ihren Branches — dort finden sich Commits, die durch reset --hard oder einen gelöschten Branch verloren gingen; Einträge verfallen standardmäßig nach 90 Tagen und existieren nur lokal.', "Conserve toutes les positions passées de HEAD et de vos branches : c'est là que réapparaissent les commits perdus par reset --hard ou par une branche supprimée ; les entrées expirent au bout de 90 jours et n'existent que sur votre machine.", 'HEAD और आपकी branch जिन जगहों पर रही हैं, सब दर्ज रखता है; reset --hard या मिटी branch से खोए commit यहीं मिलते हैं, पर प्रविष्टियाँ डिफ़ॉल्ट 90 दिन में मिट जाती हैं और यह रिकॉर्ड सिर्फ़ आपकी मशीन पर होता है।', '记录 HEAD 和各分支待过的每个位置；被 reset --hard 或删分支弄丢的提交就在这里找，条目默认 90 天后过期，而且这份记录只在你本机。', '記錄 HEAD 和各分支待過的每個位置；被 reset --hard 或刪分支弄丟的提交就在這裡找，項目預設 90 天後過期，而且這份記錄只在你本機。'],
  'git-bisect': ['커밋 구간을 반씩 갈라 문제가 처음 생긴 커밋을 찾습니다 — 끝나면 git bisect reset을 해야 하고, 잊으면 브랜치 없는 커밋 위에 그대로 남습니다.', 'Halves the range of commits to find the first bad one; you must finish with git bisect reset, or you stay parked on a detached commit.', 'Va partiendo el rango de commits en dos para encontrar el primero defectuoso; hay que terminar con git bisect reset, o te quedas en un commit desprendido.', 'Divide o intervalo de commits ao meio para achar o primeiro com defeito; termine com git bisect reset, senão você fica parado em um commit solto.', 'コミットの範囲を半分ずつ絞り、問題が最初に入ったコミットを見つけます。終わったらgit bisect resetが必要で、忘れるとブランチのないコミットに留まったままになります。', 'Halbiert den Commit-Bereich, um den ersten fehlerhaften Commit zu finden; am Ende muss git bisect reset folgen, sonst bleiben Sie auf einem losgelösten Commit stehen.', "Coupe en deux l'intervalle de commits pour trouver le premier fautif ; il faut conclure par git bisect reset, sinon vous restez sur un commit détaché.", 'commit की सीमा को आधा-आधा करके पहला ख़राब commit खोजता है; अंत में git bisect reset करना ज़रूरी है, वरना आप detached commit पर ही अटके रह जाते हैं।', '不断把提交区间对半切，找出第一个出问题的提交；结束时必须 git bisect reset，否则你会一直停在游离的提交上。', '不斷把提交區間對半切，找出第一個出問題的提交；結束時必須 git bisect reset，否則你會一直停在分離的提交上。'],
  'git-describe': ['가까운 태그를 기준으로 지금 커밋에 v1.2.0-5-gabc1234 같은 이름을 붙여 줍니다 — 기본은 주석 태그만 보므로 가벼운 태그에는 --tags가, 태그가 하나도 없으면 --always가 필요합니다.', 'Names the current commit from the nearest tag, as v1.2.0-5-gabc1234; it only sees annotated tags by default, so lightweight ones need --tags and a repository with no tag needs --always.', 'Nombra el commit actual a partir de la etiqueta más cercana, como v1.2.0-5-gabc1234; por defecto solo ve etiquetas anotadas, así que las ligeras necesitan --tags y un repositorio sin etiquetas necesita --always.', 'Nomeia o commit atual a partir da tag mais próxima, como v1.2.0-5-gabc1234; por padrão só vê tags anotadas, então as leves pedem --tags e um repositório sem tag pede --always.', '最も近いタグを起点に、今のコミットをv1.2.0-5-gabc1234のように名づけます。既定では注釈付きタグしか見ないので軽量タグには--tags、タグが無いリポジトリには--alwaysが必要です。', 'Benennt den aktuellen Commit anhand des nächsten Tags, etwa v1.2.0-5-gabc1234; standardmäßig sieht es nur annotierte Tags, leichte brauchen --tags und ein Repository ohne Tag braucht --always.', "Nomme le commit courant à partir de l'étiquette la plus proche, sous la forme v1.2.0-5-gabc1234 ; par défaut il ne voit que les étiquettes annotées, les légères exigent --tags et un dépôt sans étiquette exige --always.", 'सबसे नज़दीकी tag से मौजूदा commit को v1.2.0-5-gabc1234 जैसा नाम देता है; डिफ़ॉल्ट रूप से यह केवल annotated tag देखता है, इसलिए lightweight tag के लिए --tags और बिना tag वाले repository के लिए --always चाहिए।', '以最近的标签为基准，把当前提交命名成 v1.2.0-5-gabc1234 这样；默认只看附注标签，轻量标签要加 --tags，一个标签都没有时要加 --always。', '以最近的標籤為基準，把目前的提交命名成 v1.2.0-5-gabc1234 這樣；預設只看附註標籤，輕量標籤要加 --tags，一個標籤都沒有時要加 --always。'],
  'git-rev-parse': ['HEAD나 v1.2.0^ 같은 이름을 진짜 해시로 풀어 주고 저장소 위치도 알려 줍니다 — 스크립트에서 브랜치 이름은 --abbrev-ref HEAD로 얻고, 저장소 밖에서는 오류로 끝납니다.', 'Turns a name like HEAD or v1.2.0^ into a real hash and answers where the repository is; scripts get the branch name with --abbrev-ref HEAD, and outside a repository it exits with an error.', 'Convierte un nombre como HEAD o v1.2.0^ en un hash real y dice dónde está el repositorio; los scripts obtienen la rama con --abbrev-ref HEAD, y fuera de un repositorio termina con error.', 'Converte um nome como HEAD ou v1.2.0^ em um hash real e diz onde está o repositório; scripts pegam o nome do branch com --abbrev-ref HEAD, e fora de um repositório ele termina com erro.', 'HEADやv1.2.0^といった名前を実際のハッシュに解き、リポジトリの場所も教えます。スクリプトでブランチ名を得るには--abbrev-ref HEADを使い、リポジトリの外では失敗で終わります。', 'Löst einen Namen wie HEAD oder v1.2.0^ in einen echten Hash auf und verrät, wo das Repository liegt; Skripte holen den Branch-Namen mit --abbrev-ref HEAD, außerhalb eines Repositories endet es mit einem Fehler.', "Traduit un nom comme HEAD ou v1.2.0^ en véritable hachage et indique où se trouve le dépôt ; les scripts récupèrent le nom de branche avec --abbrev-ref HEAD, et hors d'un dépôt la commande échoue.", 'HEAD या v1.2.0^ जैसे नाम को असली hash में बदलता है और repository कहाँ है यह भी बताता है; script में branch का नाम --abbrev-ref HEAD से मिलता है, और repository के बाहर यह त्रुटि के साथ ख़त्म होता है।', '把 HEAD 或 v1.2.0^ 这类名字解析成真正的哈希，也能告诉你仓库在哪；脚本用 --abbrev-ref HEAD 取分支名，在仓库之外它会以错误退出。', '把 HEAD 或 v1.2.0^ 這類名字解析成真正的雜湊，也能告訴你儲存庫在哪；指令稿用 --abbrev-ref HEAD 取分支名，在儲存庫之外它會以錯誤結束。'],
  'git-fsck': ['개체 저장소를 검사하고 아무도 가리키지 않는 커밋을 알려 줍니다 — reflog 기록까지 사라진 뒤 잃은 작업을 찾는 두 번째 방법이며, 알려 주기만 하고 고쳐 주지는 않습니다.', 'Checks the object database and lists commits nothing points at, the second way to find work lost after a reset once the reflog entry is gone; it reports, it does not repair.', 'Revisa la base de objetos y enumera commits a los que nada apunta: la segunda forma de recuperar trabajo perdido tras un reset cuando ya no hay reflog; informa, no repara.', 'Verifica o banco de objetos e lista commits que nada aponta, o segundo jeito de achar trabalho perdido depois de um reset quando o reflog já expirou; ele relata, não conserta.', 'オブジェクトデータベースを検査し、誰も指していないコミットを教えます。reflogの記録が消えた後に失った作業を探す二番目の手段で、報告はしますが修復はしません。', 'Prüft die Objektdatenbank und listet Commits, auf die nichts zeigt — der zweite Weg zu verlorener Arbeit nach einem Reset, wenn der Reflog-Eintrag weg ist; es meldet, es repariert nicht.', "Vérifie la base d'objets et liste les commits que rien ne référence : le second moyen de retrouver un travail perdu après un reset quand le reflog a expiré ; il signale, il ne répare pas.", 'object database की जाँच करता है और उन commit को गिनाता है जिन्हें कोई नहीं दिखाता — reflog मिट जाने के बाद reset से खोया काम खोजने का दूसरा रास्ता; यह बताता है, ठीक नहीं करता।', '检查对象库并列出没有任何引用指向的提交，这是 reflog 条目也没了之后找回被 reset 弄丢的工作的第二条路；它只报告，不修复。', '檢查物件庫並列出沒有任何參照指向的提交，這是 reflog 項目也沒了之後找回被 reset 弄丟的工作的第二條路；它只報告，不修復。'],
  'git-gc': ['흩어진 개체를 묶고 아무도 안 쓰는 것을 버려 .git을 줄입니다 — --prune=now는 reflog가 붙들고 있던 커밋까지 버려서 reset을 되돌릴 안전망이 사라집니다.', 'Packs loose objects and drops unreachable ones to shrink .git; --prune=now also throws away the commits the reflog was holding, which removes your safety net for undoing a reset.', 'Empaqueta objetos sueltos y descarta los inalcanzables para reducir .git; --prune=now también tira los commits que sostenía el reflog, y con eso desaparece la red de seguridad para deshacer un reset.', 'Empacota objetos soltos e descarta os inalcançáveis para encolher o .git; --prune=now também joga fora os commits que o reflog segurava, tirando a rede de segurança para desfazer um reset.', '散らばったオブジェクトをまとめ、誰も使わないものを捨てて.gitを小さくします。--prune=nowはreflogが抱えていたコミットまで捨てるので、resetを取り消す安全網が無くなります。', 'Packt lose Objekte und verwirft unerreichbare, um .git zu verkleinern; --prune=now wirft auch die Commits weg, die der Reflog hielt, und damit das Sicherheitsnetz zum Rückgängigmachen eines Resets.', "Compacte les objets épars et supprime les inaccessibles pour réduire .git ; --prune=now jette aussi les commits que retenait le reflog, ce qui supprime le filet de sécurité pour annuler un reset.", 'बिखरे object पैक करता है और जिनका कोई सहारा नहीं उन्हें हटाकर .git छोटा करता है; --prune=now उन commit को भी फेंक देता है जिन्हें reflog पकड़े हुए था, और reset पलटने का सुरक्षा-जाल ख़त्म हो जाता है।', '把零散对象打包、丢掉无人引用的，从而缩小 .git；--prune=now 连 reflog 还拉着的提交一起丢掉，撤销 reset 的安全网也就没了。', '把零散物件打包、丟掉無人參照的，從而縮小 .git；--prune=now 連 reflog 還拉著的提交一起丟掉，撤銷 reset 的安全網也就沒了。'],

  /* ───────── git — 내보내기와 패치 ───────── */
  'git-archive': ['커밋 한 시점의 파일들을 tar나 zip으로 내보냅니다 — .git과 추적되지 않은 파일이 들어가지 않아 폴더를 그대로 압축하는 것보다 깨끗한 배포 묶음이 됩니다.', 'Exports the files of one commit as a tar or zip; .git and untracked files are left out, which makes a cleaner release archive than zipping the folder.', 'Exporta los archivos de un commit como tar o zip; deja fuera .git y los archivos sin rastrear, así el paquete de release sale más limpio que comprimir la carpeta.', 'Exporta os arquivos de um commit como tar ou zip; deixa de fora o .git e os arquivos sem rastreio, o que rende um pacote de release mais limpo que zipar a pasta.', 'あるコミット時点のファイルをtarやzipとして書き出します。.gitや追跡外のファイルが入らないので、フォルダーをそのまま圧縮するより綺麗な配布物になります。', 'Exportiert die Dateien eines Commits als tar oder zip; .git und unverfolgte Dateien bleiben draußen, das ergibt ein saubereres Release-Archiv als das Zippen des Ordners.', "Exporte les fichiers d'un commit en tar ou zip ; .git et les fichiers non suivis sont exclus, ce qui donne une archive de version plus propre qu'un zip du dossier.", 'किसी एक commit की फ़ाइलों को tar या zip के रूप में बाहर लिखता है; .git और untracked फ़ाइलें छूट जाती हैं, इसलिए फ़ोल्डर को सीधे ज़िप करने से यह साफ़ release पैकेज बनता है।', '把某个提交时的文件导出成 tar 或 zip；不会带上 .git 和未跟踪文件，所以比直接压缩文件夹更干净。', '把某個提交時的檔案匯出成 tar 或 zip；不會帶上 .git 和未追蹤檔案，所以比直接壓縮資料夾更乾淨。'],
  'git-apply': ['diff 파일을 지금 작업 파일에 입힙니다 — 커밋을 만들지 않고 패치에 적힌 작성자도 읽지 않으니, 메일로 받은 패치는 am으로 붙이는 편이 맞습니다.', 'Applies a diff file to your working tree; it makes no commit and ignores the author recorded in the patch, so mailed patches belong to am instead.', 'Aplica un archivo diff a tu árbol de trabajo; no crea commit ni lee el autor del parche, por eso los parches recibidos por correo se aplican con am.', 'Aplica um arquivo diff na sua árvore de trabalho; não cria commit nem lê o autor do patch, então patches recebidos por e-mail são caso para o am.', 'diffファイルを今の作業ツリーに当てます。コミットを作らず、パッチに書かれた作者も読まないので、メールで届いたパッチはamで当てるのが筋です。', 'Wendet eine Diff-Datei auf Ihren Arbeitsbaum an; es erzeugt keinen Commit und liest den Autor im Patch nicht, per Mail erhaltene Patches gehören daher zu am.', "Applique un fichier diff à votre copie de travail ; il ne crée aucun commit et ignore l'auteur inscrit dans le correctif, les correctifs reçus par courriel relèvent donc de am.", 'किसी diff फ़ाइल को आपके working tree पर लगाता है; यह commit नहीं बनाता और patch में लिखा लेखक भी नहीं पढ़ता, इसलिए ईमेल से आए patch के लिए am ठीक है।', '把一个 diff 文件打到当前工作区；它不创建提交，也不读取补丁里记的作者，所以邮件收到的补丁该用 am。', '把一個 diff 檔案打到目前工作區；它不建立提交，也不讀取補丁裡記的作者，所以郵件收到的補丁該用 am。'],
  'git-am': ['메일로 온 패치를 원래 작성자와 메시지 그대로 커밋으로 만듭니다 — 중간에 실패하면 그 자리에 멈추므로 --continue·--skip·--abort로 마무리해야 합니다.', 'Turns mailed patches into commits, keeping the original author and message; on failure it stops in the middle of the series, so you have to finish with --continue, --skip or --abort.', 'Convierte parches de correo en commits conservando autor y mensaje originales; si falla se detiene a mitad de la serie, y hay que cerrarla con --continue, --skip o --abort.', 'Transforma patches de e-mail em commits mantendo autor e mensagem originais; se falhar, para no meio da série, e você precisa concluir com --continue, --skip ou --abort.', 'メールで届いたパッチを、元の作者とメッセージのままコミットにします。途中で失敗するとそこで止まるので、--continue・--skip・--abortで決着させます。', 'Verwandelt gemailte Patches in Commits und behält Autor und Nachricht; bei einem Fehler bleibt es mitten in der Serie stehen, Sie müssen mit --continue, --skip oder --abort abschließen.', "Transforme des correctifs reçus par courriel en commits en conservant auteur et message ; en cas d'échec il s'arrête au milieu de la série, à vous de conclure par --continue, --skip ou --abort.", 'ईमेल से आए patch को मूल लेखक और संदेश के साथ commit बना देता है; बीच में विफल हो तो वहीं रुक जाता है, इसलिए --continue, --skip या --abort से पूरा करना पड़ता है।', '把邮件里的补丁变成提交，保留原作者和原始信息；中途失败时会停在系列中间，得用 --continue、--skip 或 --abort 收尾。', '把郵件裡的補丁變成提交，保留原作者和原始訊息；中途失敗時會停在系列中間，得用 --continue、--skip 或 --abort 收尾。'],
  'git-format-patch': ['커밋마다 메일 꼴 .patch 파일 하나씩을 만듭니다 — format-patch main은 main 자신이 아니라 main 이후의 커밋을 뜻합니다.', 'Writes one mail-shaped .patch file per commit for review by email; format-patch main means the commits after main, not main itself.', 'Escribe un archivo .patch con formato de correo por cada commit; format-patch main significa los commits posteriores a main, no main mismo.', 'Escreve um arquivo .patch em formato de e-mail por commit; format-patch main quer dizer os commits depois de main, não o próprio main.', 'コミットごとにメール形式の.patchファイルを一つ書き出します。format-patch mainはmain自身ではなく、main以降のコミットを指します。', 'Schreibt pro Commit eine mailförmige .patch-Datei; format-patch main meint die Commits nach main, nicht main selbst.', "Écrit un fichier .patch au format courriel par commit ; format-patch main désigne les commits postérieurs à main, pas main lui-même.", 'हर commit के लिए एक ईमेल-शैली .patch फ़ाइल लिखता है; format-patch main का मतलब main के बाद के commit हैं, main स्वयं नहीं।', '为每个提交写出一个邮件格式的 .patch 文件；format-patch main 指的是 main 之后的提交，不含 main 本身。', '為每個提交寫出一個郵件格式的 .patch 檔案；format-patch main 指的是 main 之後的提交，不含 main 本身。'],
  'git-shortlog': ['커밋을 사람별로 묶어 세어 줍니다 — 같은 사람이 메일 주소를 두 개 썼으면 .mailmap으로 묶지 않는 한 두 사람으로 셉니다.', 'Groups commits by author and counts them, handy for release notes; one person with two email addresses counts twice unless a .mailmap merges them.', 'Agrupa los commits por autor y los cuenta, útil para notas de versión; una persona con dos direcciones cuenta doble salvo que un .mailmap las una.', 'Agrupa os commits por autor e conta, útil para notas de versão; uma pessoa com dois e-mails conta duas vezes a menos que um .mailmap os una.', 'コミットを人ごとにまとめて数えます。同じ人がメールアドレスを二つ使っていると、.mailmapでまとめない限り二人として数えられます。', 'Gruppiert Commits nach Autor und zählt sie, praktisch für Release-Notes; eine Person mit zwei E-Mail-Adressen wird doppelt gezählt, solange keine .mailmap sie zusammenführt.', "Regroupe les commits par auteur et les compte, pratique pour des notes de version ; une même personne avec deux adresses compte deux fois sans un .mailmap pour les fusionner.", 'commit को लेखक के हिसाब से समूह बनाकर गिनता है, release notes के लिए उपयोगी; एक ही व्यक्ति के दो ईमेल हों तो .mailmap के बिना वह दो बार गिना जाता है।', '按作者把提交分组计数，写发布说明很方便；同一个人用了两个邮箱时，除非用 .mailmap 归并，否则会被算成两个人。', '按作者把提交分組計數，寫發行說明很方便；同一個人用了兩個信箱時，除非用 .mailmap 歸併，否則會被算成兩個人。'],

  /* ───────── git — 여러 작업 폴더 ───────── */
  'git-worktree': ['같은 저장소에서 두 번째 작업 폴더를 꺼내 클론 없이 두 브랜치를 동시에 다룹니다 — 한 브랜치를 두 곳에 체크아웃할 수는 없고, 폴더를 손으로 지우면 prune까지 목록에 남습니다.', 'Checks out a second working folder from the same repository so you can build two branches at once without cloning again; the same branch cannot be checked out twice, and deleting the folder by hand leaves an entry until prune.', 'Saca una segunda carpeta de trabajo del mismo repositorio para trabajar en dos ramas a la vez sin clonar otra copia; la misma rama no puede estar en dos, y borrar la carpeta a mano deja una entrada hasta prune.', 'Cria uma segunda pasta de trabalho do mesmo repositório para tocar dois branches ao mesmo tempo sem clonar de novo; o mesmo branch não pode estar em duas, e apagar a pasta na mão deixa um registro até o prune.', '同じリポジトリから二つ目の作業フォルダーを取り出し、クローンし直さずに二つのブランチを並行して扱えます。同じブランチを二か所にチェックアウトはできず、フォルダーを手で消すとpruneまで一覧に残ります。', 'Checkt einen zweiten Arbeitsordner aus demselben Repository aus, sodass zwei Branches gleichzeitig gebaut werden können, ohne erneut zu klonen; derselbe Branch kann nicht zweimal ausgecheckt sein, und ein per Hand gelöschter Ordner bleibt bis zum prune eingetragen.', "Extrait un second dossier de travail du même dépôt pour mener deux branches en parallèle sans recloner ; une même branche ne peut pas être extraite deux fois, et supprimer le dossier à la main laisse une entrée jusqu'au prune.", 'उसी repository से दूसरा working फ़ोल्डर निकालता है, जिससे दोबारा clone किए बिना दो branch साथ चल सकें; एक ही branch दो जगह checkout नहीं हो सकती, और फ़ोल्डर हाथ से मिटाने पर prune तक प्रविष्टि बची रहती है।', '从同一个仓库再签出一个工作目录，不用重新克隆就能同时开两个分支；同一个分支不能被签出两次，手动删掉目录后条目要等 prune 才清掉。', '從同一個儲存庫再簽出一個工作目錄，不用重新複製就能同時開兩個分支；同一個分支不能被簽出兩次，手動刪掉目錄後項目要等 prune 才清掉。'],
  'git-submodule': ['다른 저장소를 커밋 하나에 고정해 내 저장소 안에 둡니다 — 그냥 클론하면 폴더가 비어 있어 update --init이 필요하고, 부모가 붙드는 것은 브랜치가 아니라 커밋입니다.', 'Pins another repository at one commit inside yours; a plain clone leaves the folder empty until update --init, and the parent tracks a commit, not a branch.', 'Fija otro repositorio en un commit dentro del tuyo; un clon normal deja la carpeta vacía hasta update --init, y el padre apunta a un commit, no a una rama.', 'Fixa outro repositório em um commit dentro do seu; um clone comum deixa a pasta vazia até update --init, e o pai aponta para um commit, não para um branch.', '別のリポジトリをコミット一つに固定して自分のリポジトリ内に置きます。普通にクローンするとフォルダーは空で、update --initが必要ですし、親が押さえているのはブランチではなくコミットです。', 'Bindet ein anderes Repository an einem bestimmten Commit in Ihres ein; ein einfacher Klon lässt den Ordner leer, bis update --init läuft, und das Eltern-Repository merkt sich einen Commit, keinen Branch.', "Épingle un autre dépôt à un commit précis dans le vôtre ; un clone ordinaire laisse le dossier vide jusqu'à update --init, et le parent suit un commit, pas une branche.", 'किसी दूसरे repository को एक commit पर स्थिर करके आपके repository के भीतर रखता है; सादा clone उस फ़ोल्डर को update --init तक खाली छोड़ देता है, और parent branch नहीं, commit पकड़ता है।', '把另一个仓库固定在某个提交上，嵌进你的仓库里；普通克隆后那个目录是空的，要 update --init，而父仓库记住的是提交而不是分支。', '把另一個儲存庫固定在某個提交上，嵌進你的儲存庫裡；普通複製後那個目錄是空的，要 update --init，而父儲存庫記住的是提交而不是分支。'],

  /* ───────── pkg — node 생태계 ───────── */
  'npm-install': ['package.json에 적힌 의존성을 받아 node_modules에 넣고 package-lock.json을 갱신합니다 — npm 7부터 peer 의존성도 함께 설치되고, --production은 --omit=dev로 바뀌었습니다.', 'Downloads the dependencies package.json asks for into node_modules and updates package-lock.json; since npm 7 peer dependencies are installed too, and --production was replaced by --omit=dev.', 'Descarga en node_modules las dependencias que pide package.json y actualiza package-lock.json; desde npm 7 también instala las peer, y --production fue reemplazado por --omit=dev.', 'Baixa para node_modules as dependências que package.json pede e atualiza package-lock.json; desde o npm 7 as peer também são instaladas, e --production deu lugar a --omit=dev.', 'package.jsonに書かれた依存をnode_modulesへ入れ、package-lock.jsonを更新します。npm 7からpeer依存も一緒に入り、--productionは--omit=devに置き換わりました。', 'Lädt die in package.json genannten Abhängigkeiten nach node_modules und aktualisiert package-lock.json; seit npm 7 werden auch Peer-Abhängigkeiten installiert, und --production wurde durch --omit=dev ersetzt.', "Télécharge dans node_modules les dépendances demandées par package.json et met à jour package-lock.json ; depuis npm 7 les dépendances peer sont aussi installées, et --production a cédé la place à --omit=dev.", 'package.json में लिखी dependency को node_modules में लाता है और package-lock.json अद्यतन करता है; npm 7 से peer dependency भी अपने आप आ जाती हैं, और --production की जगह --omit=dev आ गया।', '把 package.json 里写的依赖装进 node_modules 并更新 package-lock.json；从 npm 7 起 peer 依赖也会一起装，--production 已被 --omit=dev 取代。', '把 package.json 裡寫的依賴裝進 node_modules 並更新 package-lock.json；從 npm 7 起 peer 依賴也會一起裝，--production 已被 --omit=dev 取代。'],
  'npm-ci': ['node_modules를 지우고 package-lock.json에 적힌 그대로만 설치합니다 — 잠금 파일을 고치지 않고 package.json과 어긋나면 바로 실패해서, CI에서는 install 대신 이것을 씁니다.', 'Deletes node_modules and installs exactly what package-lock.json says; it never edits the lockfile and fails outright when the lockfile and package.json disagree, which is why CI uses it instead of install.', 'Borra node_modules e instala exactamente lo que dice package-lock.json; nunca modifica el lockfile y falla si no concuerda con package.json, por eso CI lo usa en lugar de install.', 'Apaga node_modules e instala exatamente o que package-lock.json diz; nunca altera o lockfile e falha de imediato se ele divergir do package.json, por isso o CI usa este em vez de install.', 'node_modulesを消し、package-lock.jsonに書かれた通りだけを入れます。ロックファイルを書き換えず、package.jsonと食い違えばその場で失敗するので、CIではinstallの代わりにこれを使います。', 'Löscht node_modules und installiert genau das, was package-lock.json vorgibt; es ändert die Lockfile nie und bricht ab, wenn Lockfile und package.json auseinandergehen — deshalb nutzt CI es statt install.', "Supprime node_modules et installe exactement ce que dit package-lock.json ; il ne modifie jamais le fichier de verrouillage et échoue net s'il diverge de package.json, d'où son usage en CI plutôt qu'install.", 'node_modules मिटाकर ठीक वही स्थापित करता है जो package-lock.json कहता है; यह lockfile बदलता नहीं और package.json से मेल न खाने पर सीधे विफल हो जाता है, इसीलिए CI में install की जगह यही चलता है।', '先删掉 node_modules，再严格按 package-lock.json 安装；它绝不改动 lockfile，一旦和 package.json 不一致就直接失败，所以 CI 用它而不是 install。', '先刪掉 node_modules，再嚴格按 package-lock.json 安裝；它絕不改動 lockfile，一旦和 package.json 不一致就直接失敗，所以 CI 用它而不是 install。'],
  'npm-run': ['package.json의 scripts에 적어 둔 명령을 실행합니다 — 스크립트에 옵션을 넘기려면 --를 먼저 적어야 하고, run 없이 부를 수 있는 것은 start와 test뿐입니다.', 'Runs a command from the scripts section of package.json; arguments meant for the script need a bare -- first, and only start and test can be called without run.', 'Ejecuta un comando de la sección scripts de package.json; los argumentos para el script requieren un -- delante, y solo start y test pueden llamarse sin run.', 'Executa um comando da seção scripts do package.json; argumentos para o script exigem um -- antes, e só start e test podem ser chamados sem run.', 'package.jsonのscriptsに書いた命令を実行します。スクリプトへ渡す引数の前には--が必要で、runなしで呼べるのはstartとtestだけです。', 'Führt einen Befehl aus dem scripts-Abschnitt von package.json aus; Argumente für das Skript brauchen ein vorangestelltes --, und nur start und test lassen sich ohne run aufrufen.', "Exécute une commande de la section scripts de package.json ; les arguments destinés au script exigent un -- devant, et seuls start et test s'appellent sans run.", 'package.json के scripts भाग में लिखा आदेश चलाता है; script के लिए तर्क देने हों तो पहले अकेला -- चाहिए, और run के बिना सिर्फ़ start और test बुलाए जा सकते हैं।', '运行 package.json 里 scripts 段落中的命令；要把参数传给脚本，前面得先写一个单独的 --，而只有 start 和 test 可以不写 run。', '執行 package.json 裡 scripts 段落中的命令；要把參數傳給指令碼，前面得先寫一個單獨的 --，而只有 start 和 test 可以不寫 run。'],
  'npm-init': ['package.json을 만들어 줍니다 — npm init <이름> 꼴은 전혀 다른 일로, create-<이름> 패키지를 받아 실행합니다.', 'Creates a package.json; npm init <name> is a different thing altogether, downloading and running create-<name> the way npx does.', 'Crea un package.json; npm init <nombre> es otra cosa: descarga y ejecuta create-<nombre>, como hace npx.', 'Cria um package.json; npm init <nome> é outra coisa: baixa e roda create-<nome>, como o npx faz.', 'package.jsonを作ります。npm init <name>の形はまったく別で、create-<name>を取ってきて実行します。', 'Erzeugt eine package.json; npm init <name> ist etwas völlig anderes und lädt create-<name> herunter und führt es aus, wie npx.', "Crée un package.json ; npm init <nom> fait tout autre chose : il télécharge et exécute create-<nom>, comme npx.", 'package.json बना देता है; npm init <name> बिलकुल दूसरी चीज़ है — यह create-<name> उतारकर चला देता है, जैसे npx करता है।', '生成一个 package.json；npm init <名字> 是完全不同的事，它会下载并运行 create-<名字>，就像 npx 那样。', '產生一個 package.json；npm init <名字> 是完全不同的事，它會下載並執行 create-<名字>，就像 npx 那樣。'],
  'npx': ['패키지의 실행 파일을 불러 씁니다 — node_modules/.bin을 먼저 보고 없으면 원격에서 임시로 받아 오니, 오타로 엉뚱한 패키지가 실행되지 않게 하려면 --no를 붙입니다.', 'Runs a package binary, preferring node_modules/.bin and otherwise fetching it temporarily; because a typo can pull a stranger package from the registry, --no keeps it local-only.', 'Ejecuta el binario de un paquete, prefiriendo node_modules/.bin y descargándolo temporalmente si no está; como una errata puede traer un paquete ajeno, --no lo limita a lo local.', 'Executa o binário de um pacote, preferindo node_modules/.bin e baixando-o temporariamente se faltar; como um erro de digitação pode trazer um pacote alheio, --no restringe ao que é local.', 'パッケージの実行ファイルを呼び出します。node_modules/.binを先に見て、無ければ一時的に取ってくるので、打ち間違いで別のパッケージを走らせないよう--noを付けます。', 'Führt die Binärdatei eines Pakets aus, bevorzugt aus node_modules/.bin, sonst wird sie kurzzeitig geholt; da ein Tippfehler ein fremdes Paket ziehen kann, beschränkt --no auf Lokales.', "Exécute le binaire d'un paquet, en privilégiant node_modules/.bin et en le téléchargeant temporairement sinon ; une faute de frappe pouvant ramener un paquet inconnu, --no le limite au local.", 'किसी package की executable चलाता है, पहले node_modules/.bin देखता है और न मिले तो अस्थायी रूप से उतार लेता है; टाइपिंग की एक ग़लती अनजान package ले आ सकती है, इसलिए --no से इसे स्थानीय तक सीमित रखें।', '运行某个包的可执行文件，优先用 node_modules/.bin，找不到就临时下载；打错一个字就可能拉来陌生的包，加 --no 可以只用本地的。', '執行某個套件的執行檔，優先用 node_modules/.bin，找不到就臨時下載；打錯一個字就可能拉來陌生的套件，加 --no 可以只用本機的。'],
  'yarn-add': ['패키지를 넣고 yarn.lock을 갱신합니다 — yarn만 치면 install이 되고, Yarn 2부터는 yarn global add가 없어져 한 번 쓰는 도구는 yarn dlx로 실행합니다.', 'Adds a package and updates yarn.lock; plain yarn means install, and Yarn 2 dropped yarn global add, so one-off tools go through yarn dlx.', 'Añade un paquete y actualiza yarn.lock; yarn a secas equivale a install, y Yarn 2 eliminó yarn global add, así que las herramientas de un solo uso van por yarn dlx.', 'Adiciona um pacote e atualiza o yarn.lock; yarn sozinho significa install, e o Yarn 2 removeu o yarn global add, então ferramentas de uso único vão por yarn dlx.', 'パッケージを追加してyarn.lockを更新します。yarnだけならinstallの意味で、Yarn 2以降はyarn global addが無くなり、一度だけ使う道具はyarn dlxで走らせます。', 'Fügt ein Paket hinzu und aktualisiert yarn.lock; ein bloßes yarn bedeutet install, und Yarn 2 hat yarn global add entfernt, Einmal-Werkzeuge laufen daher über yarn dlx.', "Ajoute un paquet et met à jour yarn.lock ; yarn seul vaut install, et Yarn 2 a supprimé yarn global add, les outils ponctuels passent donc par yarn dlx.", 'package जोड़ता है और yarn.lock अद्यतन करता है; अकेला yarn का मतलब install है, और Yarn 2 से yarn global add हट गया, इसलिए एक बार के औज़ार yarn dlx से चलाएँ।', '添加一个包并更新 yarn.lock；只敲 yarn 等于 install，而 Yarn 2 取消了 yarn global add，一次性工具改用 yarn dlx。', '新增一個套件並更新 yarn.lock；只敲 yarn 等於 install，而 Yarn 2 取消了 yarn global add，一次性工具改用 yarn dlx。'],
  'pnpm-add': ['패키지를 공용 저장소에 두고 node_modules에서 링크로 잇습니다 — 워크스페이스 루트에서는 그냥 add를 거부하니 -w나 --filter로 어디에 넣을지 밝혀야 합니다.', 'Puts the package in a shared store and links it into node_modules; at a workspace root pnpm refuses a plain add and wants -w or --filter to say where it goes.', 'Guarda el paquete en un almacén compartido y lo enlaza en node_modules; en la raíz de un workspace pnpm rechaza un add simple y pide -w o --filter.', 'Guarda o pacote em um armazém compartilhado e o liga em node_modules; na raiz de um workspace o pnpm recusa um add simples e pede -w ou --filter.', 'パッケージを共有ストアに置き、node_modulesからリンクでつなぎます。ワークスペースのルートでは素のaddを拒むので、-wや--filterでどこへ入れるか示します。', 'Legt das Paket in einen gemeinsamen Store und verlinkt es in node_modules; in einem Workspace-Root verweigert pnpm ein einfaches add und verlangt -w oder --filter.', "Place le paquet dans un magasin partagé et le relie dans node_modules ; à la racine d'un workspace, pnpm refuse un add nu et réclame -w ou --filter.", 'package को साझा store में रखता है और node_modules में link से जोड़ता है; workspace की जड़ में pnpm सादा add मना कर देता है और -w या --filter माँगता है।', '把包放进共享存储，再在 node_modules 里用链接指过去；在 workspace 根目录 pnpm 会拒绝直接 add，要用 -w 或 --filter 指明装到哪。', '把套件放進共用儲存區，再在 node_modules 裡用連結指過去；在 workspace 根目錄 pnpm 會拒絕直接 add，要用 -w 或 --filter 指明裝到哪。'],
  'npm-audit': ['설치된 의존성에 알려진 취약점이 있는지 알려 줍니다 — fix --force는 호환이 깨지는 상위 버전까지 올리고, 개발용 깊은 의존성 경고는 손쓸 수 없는 경우가 많습니다.', 'Reports known vulnerabilities in the installed tree; fix --force will pull in breaking major versions, and warnings buried in dev-only dependencies often cannot be fixed at all.', 'Informa de vulnerabilidades conocidas en lo instalado; fix --force sube a versiones mayores que rompen, y los avisos en dependencias solo de desarrollo a menudo no tienen arreglo.', 'Relata vulnerabilidades conhecidas no que está instalado; fix --force traz versões maiores que quebram, e avisos escondidos em dependências só de desenvolvimento muitas vezes não têm solução.', '入っている依存に既知の脆弱性があるか教えます。fix --forceは互換を壊す上位バージョンまで上げ、開発用の深い依存の警告はどうにもならないことが多いです。', 'Meldet bekannte Schwachstellen im installierten Baum; fix --force zieht brechende Hauptversionen nach, und Warnungen tief in Dev-Abhängigkeiten lassen sich oft überhaupt nicht beheben.', "Signale les vulnérabilités connues dans l'arbre installé ; fix --force fait monter des versions majeures qui cassent, et les alertes enfouies dans des dépendances de développement sont souvent sans remède.", 'स्थापित पेड़ में ज्ञात कमज़ोरियाँ बताता है; fix --force ऐसे major संस्करण ले आता है जो चीज़ें तोड़ देते हैं, और dev-only गहरी dependency की चेतावनियाँ अक्सर ठीक ही नहीं हो पातीं।', '报告已安装依赖中已知的安全漏洞；fix --force 会升到会破坏兼容的大版本，而藏在开发依赖深处的告警往往根本修不了。', '報告已安裝依賴中已知的安全漏洞；fix --force 會升到會破壞相容的大版本，而藏在開發依賴深處的警告往往根本修不了。'],
  'npm-publish': ['패키지를 레지스트리에 올립니다 — @scope 이름은 기본이 비공개라 --access public이 필요하고, 한 번 올린 버전 번호는 다시 쓸 수 없으니 --dry-run으로 담길 파일부터 확인합니다.', 'Uploads the package to the registry; a scoped name is private by default so --access public is needed, and a version number can never be reused, so check the file list with --dry-run first.', 'Sube el paquete al registro; un nombre con scope es privado por defecto, de ahí --access public, y un número de versión no se puede reutilizar, así que revisa la lista de archivos con --dry-run.', 'Envia o pacote para o registro; um nome com escopo é privado por padrão, daí o --access public, e um número de versão nunca pode ser reaproveitado, então confira a lista de arquivos com --dry-run.', 'パッケージをレジストリへ上げます。@scope名は既定で非公開なので--access publicが必要で、一度使ったバージョン番号は二度と使えないため、まず--dry-runで入るファイルを確かめます。', 'Lädt das Paket in die Registry; ein Scoped Name ist standardmäßig privat, daher braucht es --access public, und eine Versionsnummer lässt sich nie wiederverwenden — prüfen Sie die Dateiliste zuerst mit --dry-run.', "Publie le paquet sur le registre ; un nom avec portée est privé par défaut, d'où --access public, et un numéro de version ne se réutilise jamais : vérifiez d'abord la liste des fichiers avec --dry-run.", 'package को registry पर चढ़ाता है; scoped नाम डिफ़ॉल्ट रूप से निजी होता है इसलिए --access public चाहिए, और कोई भी version संख्या दोबारा काम नहीं आती, सो पहले --dry-run से फ़ाइल सूची देख लें।', '把包上传到 registry；带 @scope 的名字默认是私有的，所以要加 --access public，而版本号一旦用过就不能再用，先用 --dry-run 看清会打包哪些文件。', '把套件上傳到 registry；帶 @scope 的名字預設是私有的，所以要加 --access public，而版本號一旦用過就不能再用，先用 --dry-run 看清會打包哪些檔案。'],
  'node-version': ['PATH에서 먼저 잡히는 node의 버전을 찍어 줍니다 — 버전 관리자가 셸마다 다른 것을 가리키기 때문에 편집기 터미널이나 CI가 다른 버전을 쓰는 일이 흔합니다.', 'Prints the version of the node that comes first on PATH, which is why an editor terminal or a CI job can report a different one when a version manager is in play.', 'Imprime la versión del node que aparece primero en el PATH; por eso la terminal del editor o un job de CI pueden dar otra cuando hay un gestor de versiones.', 'Imprime a versão do node que vem primeiro no PATH; por isso o terminal do editor ou um job de CI podem mostrar outra quando existe um gerenciador de versões.', 'PATHの先頭で見つかるnodeのバージョンを表示します。バージョン管理ツールがシェルごとに別のものを指すため、エディターの端末やCIが違う版を使うことがよくあります。', 'Gibt die Version des node aus, das im PATH zuerst gefunden wird — deshalb meldet ein Editor-Terminal oder ein CI-Job mit Versionsmanager oft eine andere.', "Affiche la version du node trouvé en premier dans le PATH ; d'où le fait qu'un terminal d'éditeur ou un job de CI en annonce parfois une autre quand un gestionnaire de versions est en place.", 'PATH में सबसे पहले मिलने वाले node का संस्करण छापता है; इसीलिए version manager होने पर editor का terminal या CI job दूसरा संस्करण बता सकता है।', '打印 PATH 上第一个 node 的版本；正因如此，用了版本管理器时编辑器终端或 CI 里看到的常常是另一个版本。', '印出 PATH 上第一個 node 的版本；正因如此，用了版本管理器時編輯器終端機或 CI 裡看到的常常是另一個版本。'],
  'nvm-use': ['지금 셸이 쓸 node 버전을 바꿉니다 — 그 셸에만 걸리기 때문에 새 터미널이나 CI는 기본값으로 돌아가고, nvm은 셸 함수여서 스크립트나 Makefile에서는 nvm.sh를 먼저 읽어야 합니다.', 'Switches which installed Node the current shell uses; the change lives in that shell only, so a new terminal or a CI job falls back to the default, and because nvm is a shell function a script or Makefile has to source nvm.sh first.', 'Cambia qué Node usa el shell actual; el cambio vive solo en ese shell, así que una terminal nueva o un job de CI vuelven al valor por defecto, y como nvm es una función de shell, un script o Makefile debe cargar nvm.sh antes.', 'Troca qual Node o shell atual usa; a mudança vale só naquele shell, então um terminal novo ou um job de CI volta ao padrão, e como nvm é uma função de shell, um script ou Makefile precisa carregar nvm.sh antes.', '今のシェルが使うNodeのバージョンを切り替えます。効くのはそのシェルだけなので、新しい端末やCIは既定値に戻り、nvmはシェル関数なのでスクリプトやMakefileからはnvm.shを先に読み込む必要があります。', 'Wechselt, welches installierte Node die aktuelle Shell benutzt; die Änderung gilt nur dort, ein neues Terminal oder ein CI-Job fällt auf den Standard zurück, und da nvm eine Shell-Funktion ist, muss ein Skript oder Makefile zuerst nvm.sh einlesen.', "Change la version de Node utilisée par le shell courant ; le changement ne vaut que dans ce shell, un nouveau terminal ou un job de CI revient au défaut, et comme nvm est une fonction de shell, un script ou un Makefile doit d'abord sourcer nvm.sh.", 'बदलता है कि मौजूदा shell कौन-सा स्थापित Node इस्तेमाल करे; यह बदलाव उसी shell तक रहता है, इसलिए नया terminal या CI job डिफ़ॉल्ट पर लौट आता है, और nvm एक shell function है सो script या Makefile को पहले nvm.sh source करना पड़ता है।', '切换当前 shell 使用的已装 Node 版本；改动只作用于这个 shell，新开的终端或 CI 会回到默认值，而 nvm 是个 shell 函数，脚本或 Makefile 里得先 source nvm.sh。', '切換目前 shell 使用的已安裝 Node 版本；改動只作用於這個 shell，新開的終端機或 CI 會回到預設值，而 nvm 是個 shell 函式，指令稿或 Makefile 裡得先 source nvm.sh。'],

  /* ───────── pkg — 운영체제 패키지 ───────── */
  'brew-install': ['macOS와 Linux에서 미리 빌드된 bottle을 받아 설치합니다 — 화면이 있는 앱은 --cask로 넣고, 새 버전으로 올리는 일은 install이 아니라 brew update와 brew upgrade가 맡습니다.', 'Installs a prebuilt bottle on macOS and Linux; GUI applications need --cask, and moving to a newer version is the job of brew update and brew upgrade, not of install.', 'Instala una bottle precompilada en macOS y Linux; las aplicaciones con interfaz necesitan --cask, y actualizar es tarea de brew update y brew upgrade, no de install.', 'Instala uma bottle pré-compilada no macOS e no Linux; aplicativos gráficos pedem --cask, e atualizar é tarefa de brew update e brew upgrade, não do install.', 'macOSとLinuxで、あらかじめビルドされたbottleを取って入れます。画面のあるアプリは--cask、新しい版へ上げるのはinstallではなくbrew updateとbrew upgradeの仕事です。', 'Installiert unter macOS und Linux eine vorgebaute Bottle; GUI-Programme brauchen --cask, und das Aktualisieren übernehmen brew update und brew upgrade, nicht install.', "Installe une bottle précompilée sous macOS et Linux ; les applications graphiques exigent --cask, et la mise à jour revient à brew update puis brew upgrade, pas à install.", 'macOS और Linux पर पहले से बनी bottle लाकर स्थापित करता है; ग्राफ़िकल ऐप के लिए --cask चाहिए, और नए संस्करण पर जाना brew update तथा brew upgrade का काम है, install का नहीं।', '在 macOS 和 Linux 上下载预编译的 bottle 并安装；图形界面应用要加 --cask，而升到新版本是 brew update 和 brew upgrade 的事，不是 install 的。', '在 macOS 和 Linux 上下載預先建置的 bottle 並安裝；圖形介面應用要加 --cask，而升到新版本是 brew update 和 brew upgrade 的事，不是 install 的。'],
  'apt-get-install': ['이미 받아 둔 패키지 목록에서 골라 설치합니다 — 목록이 오래되면 "Unable to locate package"가 나오니 apt-get update가 먼저이고, 스크립트에서는 사람 눈에 맞춘 apt보다 apt-get이 안전합니다.', 'Installs from the package list already on disk, so a stale list gives "Unable to locate package" until apt-get update runs; apt-get keeps a stable interface for scripts, while apt is the one meant for humans.', 'Instala desde la lista de paquetes que ya está en disco, así que una lista vieja da "Unable to locate package" hasta que corras apt-get update; apt-get mantiene una interfaz estable para scripts, mientras apt está pensado para personas.', 'Instala a partir da lista de pacotes já baixada, então uma lista velha resulta em "Unable to locate package" até rodar apt-get update; apt-get mantém uma interface estável para scripts, enquanto o apt é feito para pessoas.', 'すでに取得済みのパッケージ一覧から選んで入れます。一覧が古いと"Unable to locate package"になるのでapt-get updateが先で、スクリプトでは人向けのaptよりapt-getが安全です。', 'Installiert aus der bereits vorhandenen Paketliste; eine veraltete Liste führt zu "Unable to locate package", bis apt-get update läuft, und für Skripte ist apt-get die stabile Schnittstelle, während apt für Menschen gedacht ist.', "Installe depuis la liste de paquets déjà téléchargée : une liste périmée fait échouer la recherche du paquet jusqu'à un apt-get update, et pour les scripts apt-get offre une interface stable, apt étant destiné aux humains.", 'पहले से उतारी गई package सूची से चुनकर स्थापित करता है, इसलिए पुरानी सूची पर "Unable to locate package" आता है जब तक apt-get update न चले; script के लिए apt-get स्थिर है, जबकि apt इंसानों के लिए बना है।', '从已经下载好的软件包列表里挑着装，所以列表过期时会报 "Unable to locate package"，得先跑 apt-get update；脚本里用 apt-get 更稳，apt 是给人用的。', '從已經下載好的套件列表裡挑著裝，所以列表過期時會報 "Unable to locate package"，得先跑 apt-get update；指令稿裡用 apt-get 更穩，apt 是給人用的。'],
  'apt-update': ['패키지 목록만 새로 받아 옵니다 — 이것만으로는 아무것도 설치되거나 올라가지 않아 apt upgrade가 뒤따라야 하고, 갓 만든 컨테이너는 목록이 비어 있어 이 명령이 첫걸음입니다.', 'Refreshes the package lists and nothing else, so apt upgrade has to follow to actually install anything; a fresh container has an empty list, which makes this the first command.', 'Solo refresca las listas de paquetes, por lo que hace falta apt upgrade para instalar algo; un contenedor recién creado tiene la lista vacía, así que este es el primer comando.', 'Apenas atualiza as listas de pacotes, então apt upgrade precisa vir depois para instalar algo; um contêiner novo tem a lista vazia, e por isso este é o primeiro comando.', 'パッケージ一覧を取り直すだけです。これだけでは何も入らず上がらないのでapt upgradeが続き、作りたてのコンテナは一覧が空なのでまずこれを打ちます。', 'Aktualisiert nur die Paketlisten, installiert also nichts — dafür muss apt upgrade folgen; in einem frischen Container ist die Liste leer, deshalb ist dies der erste Befehl.', "Rafraîchit seulement les listes de paquets : il faut ensuite apt upgrade pour installer quoi que ce soit, et dans un conteneur neuf la liste est vide, d'où ce premier appel.", 'सिर्फ़ package सूचियाँ ताज़ा करता है, कुछ स्थापित या अद्यतन नहीं होता — उसके लिए apt upgrade चाहिए; नए container में सूची ख़ाली होती है, सो यही पहला आदेश है।', '只是把软件包列表刷新一遍，什么都不会装或升，要真装还得跟一个 apt upgrade；刚建好的容器列表是空的，所以这是第一条命令。', '只是把套件列表重新抓一遍，什麼都不會裝或升，要真裝還得跟一個 apt upgrade；剛建好的容器列表是空的，所以這是第一條命令。'],
  'dnf-install': ['활성 저장소에서 의존성까지 풀어 설치합니다 — 메타데이터를 스스로 만료시켜 apt처럼 update를 따로 치지 않아도 되고, RHEL 8 이후 yum은 dnf로 가는 링크이며 Fedora 41부터는 dnf5입니다.', 'Installs from the enabled repositories and resolves dependencies, refreshing metadata on its own expiry so there is no separate update step as with apt; on RHEL 8 and later yum is a link to dnf, and Fedora 41 moved to dnf5.', 'Instala desde los repositorios habilitados resolviendo dependencias y refresca los metadatos por sí solo, sin el paso de update que exige apt; en RHEL 8 y posteriores yum es un enlace a dnf, y Fedora 41 pasó a dnf5.', 'Instala dos repositórios habilitados resolvendo dependências e atualiza os metadados por conta própria, sem o passo de update do apt; no RHEL 8 e depois yum é um link para o dnf, e o Fedora 41 passou ao dnf5.', '有効なリポジトリから依存も解いて入れます。メタデータは自分で期限切れにするのでaptのようなupdateを別に打つ必要がなく、RHEL 8以降のyumはdnfへのリンクで、Fedora 41からはdnf5です。', 'Installiert aus den aktivierten Repositories samt Abhängigkeiten und erneuert die Metadaten selbstständig, ein separates update wie bei apt entfällt; ab RHEL 8 ist yum ein Link auf dnf, und Fedora 41 setzt auf dnf5.', "Installe depuis les dépôts activés en résolvant les dépendances et rafraîchit ses métadonnées tout seul, sans l'étape update d'apt ; depuis RHEL 8, yum est un lien vers dnf, et Fedora 41 est passée à dnf5.", 'सक्रिय repository से dependency सुलझाकर स्थापित करता है और metadata अपने आप ताज़ा करता है, इसलिए apt जैसा अलग update नहीं चाहिए; RHEL 8 से yum दरअसल dnf का link है, और Fedora 41 से dnf5 आ गया।', '从启用的仓库里连依赖一起装，元数据到期后自己刷新，不像 apt 那样要单独 update；RHEL 8 以后 yum 其实是指向 dnf 的链接，Fedora 41 起换成了 dnf5。', '從啟用的軟體庫裡連依賴一起裝，中介資料到期後自己更新，不像 apt 那樣要單獨 update；RHEL 8 以後 yum 其實是指向 dnf 的連結，Fedora 41 起換成了 dnf5。'],
  'pacman-s': ['Arch의 sync 저장소에서 패키지를 설치합니다 — 롤링 배포라서 -Sy로 목록만 새로 받고 설치하면 라이브러리가 어긋나는 부분 업그레이드가 되니 항상 -Syu로 함께 올립니다.', 'Installs a package from the sync repositories on Arch; because the distribution rolls, refreshing with -Sy and installing without upgrading creates a partial upgrade that breaks libraries, so use -Syu.', 'Instala un paquete desde los repositorios sync de Arch; al ser rolling, refrescar con -Sy e instalar sin actualizar produce una actualización parcial que rompe bibliotecas, así que usa -Syu.', 'Instala um pacote dos repositórios sync no Arch; como a distribuição é rolling, atualizar a lista com -Sy e instalar sem upgrade gera uma atualização parcial que quebra bibliotecas, então use -Syu.', 'Archのsyncリポジトリからパッケージを入れます。ローリングリリースなので、-Syで一覧だけ更新して入れると部分更新になりライブラリが壊れるため、必ず-Syuで一緒に上げます。', 'Installiert ein Paket aus den Sync-Repositories von Arch; da die Distribution rollend ist, erzeugt ein Refresh mit -Sy ohne Upgrade ein Teil-Upgrade, das Bibliotheken zerlegt — nutzen Sie -Syu.', "Installe un paquet depuis les dépôts sync d'Arch ; la distribution étant en rolling release, rafraîchir avec -Sy sans mettre à jour crée une mise à jour partielle qui casse les bibliothèques : utilisez -Syu.", 'Arch के sync repository से package स्थापित करता है; distribution rolling है, इसलिए -Sy से सिर्फ़ सूची ताज़ा करके स्थापित करना आधा-अधूरा upgrade बनाता है जो library तोड़ देता है — हमेशा -Syu करें।', '从 Arch 的 sync 仓库安装软件包；因为是滚动发行，只用 -Sy 刷新列表再安装会造成部分升级、把库搞坏，所以一律用 -Syu。', '從 Arch 的 sync 軟體庫安裝套件；因為是滾動發行，只用 -Sy 更新列表再安裝會造成部分升級、把函式庫搞壞，所以一律用 -Syu。'],

  /* ───────── pkg — python ───────── */
  'pip-install': ['지금 활성인 파이썬에 패키지를 넣습니다 — pip이 다른 인터프리터의 것일 수 있어 python -m pip으로 부르는 편이 안전하고, PEP 668 이후 시스템 파이썬은 가상환경 밖 설치를 거부합니다.', 'Installs a package into whichever Python is active; calling it as python -m pip avoids the classic case of pip belonging to another interpreter, and since PEP 668 a system Python refuses installs outside a virtual environment.', 'Instala un paquete en el Python activo; invocarlo como python -m pip evita el caso clásico de un pip que pertenece a otro intérprete, y desde PEP 668 un Python del sistema rechaza instalar fuera de un entorno virtual.', 'Instala um pacote no Python ativo; chamar como python -m pip evita o caso clássico de um pip que pertence a outro interpretador, e desde a PEP 668 um Python do sistema recusa instalar fora de um ambiente virtual.', '今有効なPythonにパッケージを入れます。pipが別のインタープリターのものである事故を避けるにはpython -m pipで呼ぶのが安全で、PEP 668以降のシステムPythonは仮想環境の外への導入を拒みます。', 'Installiert ein Paket in das gerade aktive Python; der Aufruf als python -m pip verhindert den Klassiker, dass pip zu einem anderen Interpreter gehört, und seit PEP 668 verweigert ein System-Python Installationen außerhalb einer virtuellen Umgebung.', "Installe un paquet dans le Python actif ; l'appeler via python -m pip évite le cas classique d'un pip appartenant à un autre interpréteur, et depuis la PEP 668 un Python système refuse d'installer hors d'un environnement virtuel.", 'जो Python सक्रिय है उसी में package स्थापित करता है; python -m pip से बुलाने पर वह पुरानी गड़बड़ टलती है जहाँ pip किसी दूसरे interpreter का होता है, और PEP 668 के बाद system Python virtual environment के बाहर स्थापना मना कर देता है।', '把包装进当前生效的那个 Python；用 python -m pip 调用可以避开 pip 其实属于另一个解释器的经典问题，而 PEP 668 之后系统 Python 会拒绝装到虚拟环境之外。', '把套件裝進目前生效的那個 Python；用 python -m pip 呼叫可以避開 pip 其實屬於另一個解譯器的經典問題，而 PEP 668 之後系統 Python 會拒絕裝到虛擬環境之外。'],
  'pip-freeze': ['설치된 패키지와 버전을 한 줄씩 찍어 requirements.txt로 만듭니다 — 직접 고른 것뿐 아니라 딸려 온 의존성까지 다 나오므로 반드시 그 가상환경 안에서 실행해야 합니다.', 'Prints every installed package with its exact version, ready to redirect into requirements.txt; it lists transitive dependencies as well as the ones you chose, so it has to be run inside the virtual environment.', 'Imprime cada paquete instalado con su versión exacta, listo para redirigir a requirements.txt; incluye las dependencias transitivas además de las que elegiste, así que hay que ejecutarlo dentro del entorno virtual.', 'Imprime cada pacote instalado com a versão exata, pronto para redirecionar para requirements.txt; lista também as dependências transitivas, então precisa rodar dentro do ambiente virtual.', '入っているパッケージと版を一行ずつ出し、requirements.txtに流し込めます。自分で選んだものだけでなく連れて来られた依存も並ぶので、必ずその仮想環境の中で実行します。', 'Gibt jedes installierte Paket mit genauer Version aus, direkt umleitbar in requirements.txt; es listet auch transitive Abhängigkeiten, muss also innerhalb der virtuellen Umgebung laufen.', "Affiche chaque paquet installé avec sa version exacte, prêt à être redirigé vers requirements.txt ; il liste aussi les dépendances transitives, il doit donc être lancé dans l'environnement virtuel.", 'स्थापित हर package को उसके ठीक संस्करण के साथ छापता है, जिसे requirements.txt में मोड़ा जा सकता है; इसमें आपकी चुनी हुई के साथ अप्रत्यक्ष dependency भी आती हैं, इसलिए इसे virtual environment के भीतर ही चलाएँ।', '把已安装的每个包和确切版本逐行打印，可直接重定向进 requirements.txt；它连带出的间接依赖也会列出，所以必须在虚拟环境里运行。', '把已安裝的每個套件和確切版本逐行印出，可直接重新導向進 requirements.txt；它連帶出的間接依賴也會列出，所以必須在虛擬環境裡執行。'],
  'venv': ['폴더 하나에 독립된 파이썬과 site-packages를 만듭니다 — 만들기만 해서는 아무 일도 없어 activate하거나 .venv/bin/python을 직접 불러야 하며, 경로가 안에 박혀 있어 폴더 이름을 나중에 바꾸면 깨집니다.', 'Creates an isolated interpreter and site-packages inside one folder; creating it does nothing until you activate it or call .venv/bin/python directly, and the paths are baked in, so renaming the folder later breaks it.', 'Crea un intérprete aislado y su site-packages en una carpeta; crearlo no hace nada hasta que lo actives o llames a .venv/bin/python, y las rutas quedan grabadas, así que renombrar la carpeta después lo rompe.', 'Cria um interpretador isolado e o site-packages dentro de uma pasta; criar não faz nada até você ativar ou chamar .venv/bin/python direto, e os caminhos ficam gravados, então renomear a pasta depois quebra tudo.', 'フォルダー一つに独立したPythonとsite-packagesを作ります。作っただけでは何も起きず、activateするか.venv/bin/pythonを直接呼ぶ必要があり、経路が中に焼き込まれるので後でフォルダー名を変えると壊れます。', 'Erzeugt einen isolierten Interpreter samt site-packages in einem Ordner; das Anlegen allein bewirkt nichts, man muss aktivieren oder .venv/bin/python direkt aufrufen, und da die Pfade fest eingebacken sind, zerbricht ein späteres Umbenennen des Ordners alles.', "Crée un interpréteur isolé et son site-packages dans un dossier ; le créer ne suffit pas, il faut l'activer ou appeler directement .venv/bin/python, et comme les chemins y sont inscrits, renommer le dossier ensuite le casse.", 'एक फ़ोल्डर में अलग interpreter और site-packages बनाता है; बनाने से कुछ नहीं होता, उसे activate करना या सीधे .venv/bin/python बुलाना पड़ता है, और रास्ते अंदर लिखे होते हैं सो बाद में फ़ोल्डर का नाम बदलने पर यह टूट जाता है।', '在一个文件夹里建出独立的解释器和 site-packages；只建不用没有任何效果，得先 activate 或直接调用 .venv/bin/python，而且路径是写死在里面的，事后改文件夹名就坏了。', '在一個資料夾裡建出獨立的解譯器和 site-packages；只建不用沒有任何效果，得先 activate 或直接呼叫 .venv/bin/python，而且路徑是寫死在裡面的，事後改資料夾名稱就壞了。'],

  /* ───────── pkg — docker ───────── */
  'docker-run': ['이미지에서 컨테이너를 새로 만들어 띄웁니다 — 두 번 치면 컨테이너가 둘이 되니 멈춘 것을 다시 켜는 일은 docker start이고, -p 없이는 host에서 닿지 않으며 -v 없이 쓴 것은 컨테이너와 함께 사라집니다.', 'Creates and starts a new container from an image every time, so running it twice gives you two containers and restarting an existing one is docker start; without -p nothing is reachable from the host, and without -v whatever it writes dies with the container.', 'Crea y arranca un contenedor nuevo desde una imagen cada vez, así que ejecutarlo dos veces deja dos contenedores y reiniciar uno existente es docker start; sin -p nada es accesible desde el host, y sin -v lo escrito muere con el contenedor.', 'Cria e inicia um contêiner novo a partir da imagem toda vez, então rodar duas vezes deixa dois contêineres e reiniciar um existente é docker start; sem -p nada é alcançável do host, e sem -v o que for escrito morre com o contêiner.', 'イメージから毎回新しいコンテナを作って起動します。二度打てばコンテナが二つになり、止まったものを起こすのはdocker startで、-pが無ければホストから届かず、-vが無ければ書いたものはコンテナと一緒に消えます。', 'Erzeugt und startet jedes Mal einen neuen Container aus einem Image, zweimal ausgeführt gibt es also zwei, und einen bestehenden startet docker start; ohne -p ist nichts vom Host erreichbar, und ohne -v stirbt alles Geschriebene mit dem Container.', "Crée et démarre un nouveau conteneur à partir d'une image à chaque appel : lancé deux fois, il en existe deux, et pour relancer un conteneur arrêté c'est docker start ; sans -p rien n'est joignable depuis l'hôte, et sans -v ce qui est écrit disparaît avec le conteneur.", 'हर बार image से एक नया container बनाकर चलाता है, इसलिए दो बार चलाने पर दो container बन जाते हैं और रुके हुए को फिर चलाना docker start है; -p के बिना host से कुछ नहीं पहुँचता, और -v के बिना जो लिखा जाता है container के साथ मिट जाता है।', '每次都会从镜像新建并启动一个容器，所以敲两次就有两个容器，重启已有的那个要用 docker start；不加 -p 主机访问不到，不加 -v 写下的东西会随容器一起消失。', '每次都會從映像新建並啟動一個容器，所以敲兩次就有兩個容器，重新啟動已有的那個要用 docker start；不加 -p 主機連不到，不加 -v 寫下的東西會隨容器一起消失。'],
  'docker-ps': ['지금 돌고 있는 컨테이너만 보여줍니다 — 시작하자마자 죽은 컨테이너는 -a를 붙여야 보이니, run이 아무 일도 안 한 것처럼 보이면 여기를 봅니다.', 'Lists only the containers running right now; one that exited straight after start is invisible until -a, which is where to look when docker run seems to have done nothing.', 'Lista solo los contenedores que están corriendo; uno que murió justo al arrancar no aparece hasta usar -a, y ahí hay que mirar cuando docker run parece no haber hecho nada.', 'Lista só os contêineres em execução; um que saiu logo após iniciar fica invisível até usar -a, e é ali que se olha quando docker run parece não ter feito nada.', '今動いているコンテナだけを並べます。起動直後に落ちたものは-aを付けないと見えないので、runが何もしなかったように見えるときはここを見ます。', 'Listet nur die aktuell laufenden Container; einer, der direkt nach dem Start beendet wurde, erscheint erst mit -a — dort schaut man nach, wenn docker run scheinbar nichts getan hat.', "N'affiche que les conteneurs en cours d'exécution ; celui qui s'est arrêté juste après le démarrage reste invisible sans -a, et c'est là qu'il faut regarder quand docker run semble n'avoir rien fait.", 'सिर्फ़ अभी चल रहे container दिखाता है; जो शुरू होते ही बंद हो गया वह -a लगाने तक नहीं दिखता, और जब docker run ने कुछ न किया हो तो वहीं देखना चाहिए।', '只列出此刻正在运行的容器；启动后马上退出的那个要加 -a 才看得到，docker run 好像什么都没做时就该去那里看。', '只列出此刻正在執行的容器；啟動後馬上結束的那個要加 -a 才看得到，docker run 好像什麼都沒做時就該去那裡看。'],
  'docker-build': ['Dockerfile로 이미지를 만듭니다 — 끝의 점은 데몬에게 보낼 빌드 컨텍스트라서 폴더가 크면 빌드가 느려지고(.dockerignore로 줄입니다), COPY는 그 컨텍스트 안의 파일만 볼 수 있습니다.', 'Builds an image from a Dockerfile; the trailing dot is the build context sent to the daemon, so a fat folder makes builds slow until .dockerignore trims it, and COPY can only see files inside that context.', 'Construye una imagen desde un Dockerfile; el punto final es el contexto que se envía al demonio, así que una carpeta enorme ralentiza la construcción hasta que .dockerignore la recorta, y COPY solo ve archivos dentro de ese contexto.', 'Constrói uma imagem a partir de um Dockerfile; o ponto no fim é o contexto enviado ao daemon, então uma pasta gorda deixa o build lento até o .dockerignore enxugar, e o COPY só vê arquivos dentro desse contexto.', 'Dockerfileからイメージを作ります。末尾の点はデーモンへ送るビルドコンテキストなので、フォルダーが大きいとビルドが遅くなり(.dockerignoreで削ります)、COPYはそのコンテキスト内のファイルしか見えません。', 'Baut ein Image aus einem Dockerfile; der Punkt am Ende ist der Build-Kontext, der an den Daemon geht — ein dicker Ordner bremst den Build, bis .dockerignore ihn kürzt, und COPY sieht nur Dateien innerhalb dieses Kontexts.', "Construit une image à partir d'un Dockerfile ; le point final est le contexte envoyé au démon, donc un dossier volumineux ralentit la construction jusqu'à ce que .dockerignore l'allège, et COPY ne voit que les fichiers de ce contexte.", 'Dockerfile से image बनाता है; अंत का बिंदु वह build context है जो daemon को भेजा जाता है, इसलिए भारी फ़ोल्डर build धीमा कर देता है (.dockerignore से छाँटें), और COPY उसी context के भीतर की फ़ाइलें ही देख पाता है।', '按 Dockerfile 构建镜像；结尾那个点是要送给守护进程的构建上下文，目录太大构建就慢，得靠 .dockerignore 瘦身，而 COPY 只能看到上下文里的文件。', '依 Dockerfile 建置映像；結尾那個點是要送給守護行程的建置環境，目錄太大建置就慢，得靠 .dockerignore 瘦身，而 COPY 只能看到該環境裡的檔案。'],
  'docker-compose-up': ['compose.yaml에 적힌 서비스를 한 묶음으로 띄웁니다 — 하이픈이 붙은 docker-compose는 은퇴한 v1이고 지금은 docker compose 플러그인이며, 이미 있는 컨테이너는 --build나 --force-recreate 없이는 그대로 다시 쓰입니다.', 'Starts every service in compose.yaml as one project; the hyphenated docker-compose is the retired v1 while docker compose is the v2 plugin, and existing containers are reused unless you pass --build or --force-recreate.', 'Arranca todos los servicios de compose.yaml como un proyecto; el docker-compose con guion es la v1 retirada y docker compose es el plugin v2, y los contenedores existentes se reutilizan salvo con --build o --force-recreate.', 'Sobe todos os serviços do compose.yaml como um projeto; o docker-compose com hífen é a v1 aposentada e docker compose é o plugin v2, e contêineres existentes são reaproveitados a menos que use --build ou --force-recreate.', 'compose.yamlに書かれたサービスを一まとまりとして立ち上げます。ハイフン付きのdocker-composeは引退したv1で今はdocker composeプラグインであり、既にあるコンテナは--buildや--force-recreateがなければそのまま再利用されます。', 'Startet alle Dienste aus compose.yaml als ein Projekt; das bindestrichige docker-compose ist das ausgemusterte v1, docker compose das v2-Plugin, und vorhandene Container werden ohne --build oder --force-recreate weiterverwendet.', "Démarre tous les services de compose.yaml comme un même projet ; docker-compose avec tiret est la v1 retirée alors que docker compose est le plugin v2, et les conteneurs existants sont réutilisés sauf avec --build ou --force-recreate.", 'compose.yaml में लिखी सभी service को एक परियोजना के रूप में चालू करता है; हाइफ़न वाला docker-compose सेवानिवृत्त v1 है और अब docker compose plugin है, और मौजूदा container --build या --force-recreate के बिना वैसे ही दोबारा काम में आते हैं।', '把 compose.yaml 里的所有服务当成一个项目一起启动；带连字符的 docker-compose 是已退役的 v1，现在是 docker compose 插件，而已存在的容器不加 --build 或 --force-recreate 就会被直接复用。', '把 compose.yaml 裡的所有服務當成一個專案一起啟動；帶連字號的 docker-compose 是已退役的 v1，現在是 docker compose 外掛，而已存在的容器不加 --build 或 --force-recreate 就會被直接重用。'],
  'docker-exec': ['이미 돌고 있는 컨테이너 안에서 다른 프로세스를 실행합니다 — 멈춘 컨테이너에는 쓸 수 없고, 가벼운 이미지에는 bash가 없어 sh로 들어가야 합니다.', 'Runs another process inside a container that is already running; it fails on a stopped one, and slim images have no bash, so you go in with sh.', 'Ejecuta otro proceso dentro de un contenedor que ya está corriendo; falla si está detenido, y las imágenes slim no traen bash, así que entras con sh.', 'Executa outro processo dentro de um contêiner que já está rodando; falha se ele estiver parado, e imagens slim não têm bash, então entra-se com sh.', 'すでに動いているコンテナの中で別のプロセスを走らせます。止まっているコンテナには使えず、軽いイメージにはbashが無いのでshで入ります。', 'Startet einen weiteren Prozess in einem bereits laufenden Container; bei einem gestoppten schlägt es fehl, und Slim-Images haben kein bash, dort nimmt man sh.', "Lance un autre processus dans un conteneur déjà en marche ; il échoue sur un conteneur arrêté, et les images slim n'ont pas de bash, on entre donc avec sh.", 'पहले से चल रहे container के भीतर दूसरा process चलाता है; रुके हुए container पर यह विफल हो जाता है, और slim image में bash नहीं होता सो sh से घुसना पड़ता है।', '在一个已经运行的容器里再跑一个进程；容器停着就会失败，而精简镜像里没有 bash，得用 sh 进去。', '在一個已經執行的容器裡再跑一個行程；容器停著就會失敗，而精簡映像裡沒有 bash，得用 sh 進去。'],
  'docker-logs': ['컨테이너의 주 프로세스가 stdout·stderr로 쓴 것을 보여줍니다 — 앱이 컨테이너 안 파일에 로그를 쓰면 여기에는 아무것도 안 나오고, 컨테이너를 지우면 로그도 함께 사라집니다.', 'Shows what the main process of the container wrote to stdout and stderr; an app that logs into a file inside the container shows nothing here, and the logs disappear with the container.', 'Muestra lo que el proceso principal del contenedor escribió en stdout y stderr; una app que escribe su log en un archivo interno no muestra nada aquí, y los logs desaparecen con el contenedor.', 'Mostra o que o processo principal do contêiner escreveu em stdout e stderr; um app que grava log em arquivo interno não aparece aqui, e os logs desaparecem junto com o contêiner.', 'コンテナの主プロセスがstdoutとstderrに書いたものを見せます。アプリがコンテナ内のファイルにログを書いていると何も出ず、コンテナを消すとログも一緒に消えます。', 'Zeigt, was der Hauptprozess des Containers auf stdout und stderr geschrieben hat; eine App, die in eine Datei im Container loggt, erscheint hier nicht, und mit dem Container verschwinden die Logs.', "Affiche ce que le processus principal du conteneur a écrit sur stdout et stderr ; une application qui journalise dans un fichier interne n'y apparaît pas, et les journaux disparaissent avec le conteneur.", 'container के मुख्य process ने stdout और stderr पर जो लिखा वही दिखाता है; अगर app container के भीतर किसी फ़ाइल में log लिखता है तो यहाँ कुछ नहीं आता, और container मिटने पर log भी चले जाते हैं।', '显示容器主进程写到 stdout 和 stderr 的内容；如果应用把日志写进容器里的文件，这里什么都看不到，而容器一删日志也跟着没了。', '顯示容器主行程寫到 stdout 和 stderr 的內容；如果應用把日誌寫進容器裡的檔案，這裡什麼都看不到，而容器一刪日誌也跟著沒了。'],
};
